schemas.schema-01-systematic.prisma:
/// Channel entity - This implements the marketplace channel management requirement from the system architecture documentation. Represents a sales or display channel (e.g., main shopfront, special event shop, mobile app, partner portal). Maintains 3NF by storing only atomic, non-redundant channel information. For example, a separate channel for a Black Friday event can be created and referenced by products, categories, etc. Key relationships: referenced by sections, categories, potentially products in other domains. Special behaviors: channel code must be unique; channel can be enabled/disabled for serving.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each shop channel.
  id String @id @db.Uuid

  /// Channel code - Implements unique channel identifier requirement. Used for programmatic reference (e.g., 'main', 'event2025'). Ensures normalization by separating channel logic from display names. Example: code='main', code='mobile'. Unique.
  code String

  /// Channel display name - Implements business need for human-readable identification. Shown in admin/UI selectors. Fully normalized from code. Example: 'Main Shop', 'Mobile Exclusive'.
  name String

  /// Whether this channel is active and visible - Implements channel status management. Enables/disables serving of products/content via this channel. Example: enabled=true for an active channel.
  enabled Boolean

  /// Ordering of channels in UI - For business control of display order. Example: sort_order=1 for highest.
  sort_order Int @db.Integer

  /// Timestamp of channel creation - Implements audit trail requirement. Normalized as atomic event timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update. For audit and synchronization.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shop_sections ai_shop_sections[]
  ai_shop_categories ai_shop_categories[]
  ai_shop_posts ai_shop_posts[]

  @@unique([code])
  @@index([enabled])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Section entity - Implements the marketplace section management requirement from the system architecture document. Represents a logical grouping within a channel (e.g., home, sale, electronics landing). Maintains 3NF by separating section info from channel, category, display logic. Example: A 'Deals' section in 'main' channel. Key relationships: references ai_shop_channels via channel_id. Special behaviors: section code is unique within channel.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each shop section.
  id String @id @db.Uuid

  /// Parent channel's {@link ai_shop_channels.id} - Connects section to its parent channel, enforcing referential integrity.
  ai_shop_channel_id String @db.Uuid

  /// Section code (unique within channel) - Business need for programmatic reference. Example: 'home', 'products', 'outlet'.
  code String

  /// Section name for display in UI - Human-readable identifier. Example: 'Homepage', 'Outlet'.
  name String

  /// Ordering of sections within a channel - Controls display sequence.
  sort_order Int @db.Integer

  /// Whether section is active.
  enabled Boolean

  /// Timestamp of section creation.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  section_channel ai_shop_channels @relation(fields: [ai_shop_channel_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_channel_id, code])
  @@index([ai_shop_channel_id, enabled])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Platform configuration entity - Implements global/system configuration requirement from architecture documentation. Each row is a single configuration parameter (name-value pair), enabling dynamic and scalable platform settings. Maintains strict normalization (no redundant or precomputed settings). Example: max_cart_size, maintenance_mode. Can be used by system at runtime. Special behaviors: param_name unique.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each configuration parameter.
  id String @id @db.Uuid

  /// Configuration parameter name - Implements atomic, normalized key/value store of platform configuration. Example: 'max_cart_size', 'maintenance_mode'. Unique.
  param_name String

  /// Value for the configuration parameter - May be stringified JSON for complex settings. Example: 'true', '50', '{"allowed":true}'.
  param_value String

  /// Human-readable description of what this config controls. Assists admin understanding, auditing. Example: 'The maximum number of items allowed in a cart.'
  description String?

  /// Timestamp when configuration was created. Enables auditing, rollback, compliance with 3NF.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([param_name])
  @@index([created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Category entity - Implements category taxonomy/management requirement from system documentation. Represents hierarchical or flat categories used in product organization, navigation, filtering. Maintains full 3NF normalization by having explicit parent_id for trees and linking only via foreign keys. Example: 'Electronics' (parent=null), 'Laptops' (parent=Electronics ID). Key relationships: references ai_shop_channels for scoping to channel; parent_id for nesting. Special behaviors: unique per channel + code. Distributed (multi-tenant) shops supported.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique for each category.
  id String @id @db.Uuid

  /// Channel containing this category {@link ai_shop_channels.id}. Enables multi-channel support for categories.
  ai_shop_channel_id String @db.Uuid

  /// Parent category's {@link ai_shop_categories.id} (can be null for root categories). Implements hierarchical taxonomy as required. Null for category roots.
  parent_id String? @db.Uuid

  /// Category code (unique within channel, for this tree level) - For programmatic use. Example: 'electronics', 'shoes'.
  code String

  /// Category display name - UI/admin view. Example: 'Laptops'.
  name String

  /// Position/display order among siblings. Used for drag-sort in admin UIs. Example: sort_order=4 for 4th in parent.
  sort_order Int @db.Integer

  /// Whether category is shown to end-users. For blacklist/hiding logic. Example: 'enabled' = false hides everywhere.
  enabled Boolean

  /// Timestamp of category creation. Ensures auditability and history.
  created_at DateTime @db.Timestamptz

  /// Time last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  category_channel ai_shop_channels @relation(fields: [ai_shop_channel_id], references: [id], onDelete: Cascade)
  category_parent ai_shop_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_shop_categories[] @relation("recursive")
  ai_shop_products ai_shop_products[]

  @@index([parent_id])

  @@unique([ai_shop_channel_id, parent_id, code])
  @@index([ai_shop_channel_id, parent_id])
  @@index([enabled])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// File entity - Implements file management requirement for all uploads in the platform (systematic, product, bulletin, user, etc.). Enables normalized, auditable file storage and access metadata. Maintains 3NF: links to nothing, stores only atomic file data. Example: a product image, a user-uploaded attachment. Key relationships: referenced via file_id by attachments, images, etc., in other domains. Special behaviors: store both original file name and unique storage URI; unique uri enforced.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_files {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique file identifier.
  id String @id @db.Uuid

  /// Original file name as uploaded - For UI/admin display. Example: 'invoice2025.pdf'.
  original_name String

  /// Persistent storage URI or path (e.g., cloud url, s3 key). For programmatic file retrieval. Example: 'files/2025/07/report.pdf'. Unique.
  uri String @db.VarChar(80000)

  /// File mime type, e.g., image/png, application/pdf. Used for preview, content validation.
  mime_type String

  /// Size of file in bytes. For auditing, quota enforcement. Example: 51288.
  size_bytes Int @db.Integer

  /// Name of uploader (if available at upload time).
  uploader_name String?

  /// Timestamp when file was uploaded. Audit and traceability.
  uploaded_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shop_post_attachments ai_shop_post_attachments[]
  ai_shop_comment_attachments ai_shop_comment_attachments[]

  @@unique([uri])
  @@index([mime_type])
  @@index([original_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Audit log entity - Implements platform-wide audit and compliance logging, as per architecture compliance documentation. Maintains normalized logs: each change, action, or critical event is a row. Provides traceability for GDPR, disputes, admin intervention. Normalized to ensure no event denormalization or aggregation. Example: order status change log, admin action log. Can be used to reconstruct user or system activity. Key relationships: none in this domain, but could reference user/seller/admin IDs in other domains. Special behaviors: event_id unique for deduplication; event_type indexed for fast filtering.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Log entry identifier.
  id String @id @db.Uuid

  /// Unique event identifier for idempotency/deduplication. Example: 'ORD20250722-38'.
  event_id String

  /// Event type code (e.g., 'USER_LOGIN', 'ORDER_CANCELED', 'CONFIG_EDIT'). Used for fast querying and filtering.
  event_type String

  /// Actor identifier (references user, seller, admin, etc. in other domains). Nullable for system-initiated events.
  actor_id String? @db.Uuid

  /// Role of actor, e.g., 'customer', 'seller', 'admin', or null for system.
  actor_role String?

  /// Table affected by event, for traceability. Example: 'ai_shop_orders'.
  target_table String?

  /// Row/entity affected, allows for multi-entity logging without foreign key enforcement.
  target_id String? @db.Uuid

  /// Detailed JSON blob (as string) describing event content, before/after states. Example: '{"from":"pending","to":"paid"}'.
  details String?

  /// Timestamp when event occurred, precise to at least 1 second.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([event_id])
  @@index([event_type])
  @@index([actor_id])
  @@index([created_at])
  @@index([details(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// AI Shop Customer Entity - This implements customer identity, onboarding, and profile core requirements from the Customer Management spec. Business Purpose: Represents end-users (buyers). Links to profile; authentication base. Maintains 3NF normalization; preference/secondary contacts in profile. Example: Used in onboarding and customer login. Key relationships: 1:1 with ai_shop_customer_profiles. Special: GDPR, deletion, audit required.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Globally unique customer identifier.
  id String @id @db.Uuid

  /// Customer Email. Primary login and contact identity. Unique and required. Example: For notifications and login.
  email String

  /// Customer Phone Number. For notifications or MFA. Optional.
  phone String?

  /// Lifecycle/account status (active/withdrawn/suspended). Used for access control. Required. Application-level enum.
  status String

  /// Timestamp of account creation.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shop_auth_providers ai_shop_auth_providers[]
  ai_shop_user_sessions ai_shop_user_sessions[]
  ai_shop_customer_profiles ai_shop_customer_profiles?
  ai_shop_posts ai_shop_posts[]
  ai_shop_post_comments ai_shop_post_comments[]
  ai_shop_post_snapshots ai_shop_post_snapshots[]
  ai_shop_post_recommendations ai_shop_post_recommendations[]
  ai_shop_post_reports ai_shop_post_reports[]
  ai_shop_carts ai_shop_carts?
  ai_shop_orders ai_shop_orders[]
  ai_shop_order_refunds ai_shop_order_refunds[]
  ai_shop_return_requests ai_shop_return_requests[]
  ai_shop_order_abandonments ai_shop_order_abandonments[]
  ai_shop_coupon_assignments ai_shop_coupon_assignments[]
  ai_shop_deposits ai_shop_deposits[]
  ai_shop_mileages ai_shop_mileages[]
  ai_shop_donation_coupons ai_shop_donation_coupons[]
  ai_shop_inquiries ai_shop_inquiries[]
  ai_shop_reviews ai_shop_reviews[]
  ai_shop_review_ratings ai_shop_review_ratings[]
  ai_shop_favorites_products ai_shop_favorites_products[]
  ai_shop_favorites_inquiries ai_shop_favorites_inquiries[]
  ai_shop_favorites_addresses ai_shop_favorites_addresses[]
  ai_shop_favorites_notifications ai_shop_favorites_notifications[]

  @@unique([email])
  @@index([status])
}

/// AI Shop Seller Entity - implements onboarding and approval processes for marketplace sellers. Business Purpose: Represents merchant identity (legal/business), separate from product or inventory. Follows 3NF; all contact details in profile. Example: Onboarding reviewed by admin. Key: 1:1 with ai_shop_seller_profiles. Special: Approval required, audit logs tracked.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique seller identifier.
  id String @id @db.Uuid

  /// Official Store/Business Name. Used in public shop, invoice, and admin review. Required and unique.
  business_name String

  /// Business Registration Number, government ID/legal identifier. Unique.
  business_registration_number String

  /// Account (onboarding/active/suspended) status. Controls access. Enum at app layer.
  status String

  /// Timestamp when admin approved this seller. Nullable if not yet reviewed.
  approved_at DateTime? @db.Timestamptz

  /// When seller started onboarding.
  created_at DateTime @db.Timestamptz

  /// When seller account was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shop_auth_providers ai_shop_auth_providers[]
  ai_shop_user_sessions ai_shop_user_sessions[]
  ai_shop_seller_profiles ai_shop_seller_profiles?
  ai_shop_products ai_shop_products[]
  ai_shop_inventories ai_shop_inventories[]
  ai_shop_product_import_logs ai_shop_product_import_logs[]
  ai_shop_posts ai_shop_posts[]
  ai_shop_post_comments ai_shop_post_comments[]
  ai_shop_post_snapshots ai_shop_post_snapshots[]
  ai_shop_post_recommendations ai_shop_post_recommendations[]
  ai_shop_post_reports ai_shop_post_reports[]
  ai_shop_orders ai_shop_orders[]
  ai_shop_order_deliveries ai_shop_order_deliveries[]
  ai_shop_deposits ai_shop_deposits[]
  ai_shop_inquiry_replies ai_shop_inquiry_replies[]

  @@unique([business_registration_number])
  @@index([status])
}

/// AI Shop Admin Entity - implements storage for platform/admin users. Business purpose: Used for management, onboarding, audit/logging, admin privileges. 3NF; admin-specifics in separate profile. Used in audit logs, permission checks. One-to-one with ai_shop_admin_profiles. Special: High-security; audit required.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_admins {
  //----
  // COLUMNS
  //----
  /// Primary key. Unique, non-sequential admin identity.
  id String @id @db.Uuid

  /// Unique admin username for login and audit tracing. Required.
  username String

  /// Admin account status (active/suspended/pending). Access control.
  status String

  /// Timestamp for admin account creation.
  created_at DateTime @db.Timestamptz

  /// Latest update timestamp for admin account.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shop_auth_providers ai_shop_auth_providers[]
  ai_shop_user_sessions ai_shop_user_sessions[]
  ai_shop_admin_profiles ai_shop_admin_profiles?
  ai_shop_posts ai_shop_posts[]
  ai_shop_post_comments ai_shop_post_comments[]
  ai_shop_post_snapshots ai_shop_post_snapshots[]
  ai_shop_post_reports ai_shop_post_reports[]
  ai_shop_moderation_actions ai_shop_moderation_actions[]
  ai_shop_order_status_histories ai_shop_order_status_histories[]
  ai_shop_inquiry_replies ai_shop_inquiry_replies[]
  ai_shop_review_moderations ai_shop_review_moderations[]
  ai_shop_inquiry_moderations ai_shop_inquiry_moderations[]

  @@unique([username])
  @@index([status])
}

/// AI Shop Auth Provider mapping for external login/OAuth/2FA association for all actor types. Business: Links customer, seller, or admin to social/OAuth/email/multi-factor. 3NF: provider linkage is always separate from credentials. Example: Google login, or SMS 2fa, 1:many with actors. Special: All FKs within actor tables; unique per (provider_type, external_id, [actor_id]).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_auth_providers {
  //----
  // COLUMNS
  //----
  /// Primary key. Unique linkage record.
  id String @id @db.Uuid

  /// Customer FK - links to ai_shop_customers.id if provider for a customer.
  customer_id String? @db.Uuid

  /// Seller FK - links to ai_shop_sellers.id if associated with seller.
  seller_id String? @db.Uuid

  /// Admin FK - links to ai_shop_admins.id if associated with admin.
  admin_id String? @db.Uuid

  /// Type (google/kakao/apple/naver/email/totp/sms/etc). Required.
  provider_type String

  /// External (provider) unique user id.
  external_id String

  /// Timestamp when linkage established. Required.
  linked_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer_auth_provider_fk ai_shop_customers? @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  seller_auth_provider_fk ai_shop_sellers? @relation(fields: [seller_id], references: [id], onDelete: Cascade)
  admin_auth_provider_fk ai_shop_admins? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([customer_id])
  @@index([seller_id])
  @@index([admin_id])

  @@unique([provider_type, external_id, customer_id])
  @@unique([provider_type, external_id, seller_id])
  @@unique([provider_type, external_id, admin_id])
  @@index([linked_at])
}

/// AI Shop User Session table - tracks login/concurrent session/audit for any customer, seller, or admin. All FKs within actor tables. Used to control history, forced logout, device management. Special: Session FK to a single actor; allows multiple concurrent per user. 3NF. Example: Forced logout sets terminated_at.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary key. Unique session context.
  id String @id @db.Uuid

  /// FK to customer for session. Nullable.
  customer_id String? @db.Uuid

  /// FK to seller for session. Nullable.
  seller_id String? @db.Uuid

  /// FK to admin for session. Nullable.
  admin_id String? @db.Uuid

  /// Login token. Unique per session. Required.
  session_token String

  /// Session creation timestamp.
  issued_at DateTime @db.Timestamptz

  /// Expiration timestamp. Required.
  expires_at DateTime @db.Timestamptz

  /// If forcibly ended, the timestamp here. Nullable.
  terminated_at DateTime? @db.Timestamptz

  /// Session IP address (for audit/tracing). Required.
  ip_address String

  //----
  // RELATIONS
  //----
  customer_session_fk ai_shop_customers? @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  seller_session_fk ai_shop_sellers? @relation(fields: [seller_id], references: [id], onDelete: Cascade)
  admin_session_fk ai_shop_admins? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([customer_id])
  @@index([seller_id])
  @@index([admin_id])

  @@unique([session_token])
  @@index([issued_at])
  @@index([expires_at])
}

/// AI Shop Customer Profile - extended preferences, contacts, addresses, privacy for each customer. All profile data separate from core customer for 3NF. Key: 1:1 to ai_shop_customers. Used for personalization, GDPR and preference data. Special: Nullable fields for optional attributes.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_customer_profiles {
  //----
  // COLUMNS
  //----
  /// Primary key. Unique profile identity.
  id String @id @db.Uuid

  /// FK to ai_shop_customers.id, enforced unique (1:1).
  customer_id String @db.Uuid

  /// Full customer name for address and display. Required.
  name String

  /// Serialised preferences JSON. Optional.
  preferences String?

  /// Date of birth (if collected for compliance/age). Optional.
  dob DateTime? @db.Timestamptz

  /// Gender for analytics/marketing (nullable, optional).
  gender String?

  /// Language/locale code (fr, ko, en...). Optional.
  locale String?

  /// Serialized multi-address JSON. Optional, for customer with multi-ship support.
  shipping_addresses String?

  /// Timestamp when profile created.
  created_at DateTime @db.Timestamptz

  /// Last profile update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer_profile_fk ai_shop_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_shop_favorites_addresses ai_shop_favorites_addresses[]

  @@unique([customer_id])
  @@index([locale])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// AI Shop Seller Profile - all extended seller business/contact details for compliance/audit. All contacts and documents here; seller table only core legal ID info. Key: 1:1 to ai_shop_sellers. Used for onboarding, KYC, compliance review.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_seller_profiles {
  //----
  // COLUMNS
  //----
  /// Primary key. Unique seller profile identity.
  id String @id @db.Uuid

  /// FK to ai_shop_sellers.id, enforced unique (1:1).
  seller_id String @db.Uuid

  /// Primary legal/business contact name. Required.
  contact_name String

  /// Contact email (distinct from login/business email). Required.
  contact_email String

  /// Business phone (for compliance, shipping, support). Optional.
  company_phone String?

  /// Business address. Used for legal/compliance. Optional.
  address String?

  /// JSON list of attached/additional files or KYC uploads (referenced to file storage system). Optional.
  kyc_documents String?

  /// Timestamp when seller profile record created.
  created_at DateTime @db.Timestamptz

  /// Last update to seller profile.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller_profile_fk ai_shop_sellers @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  @@unique([seller_id])
  @@index([contact_email])
  @@index([contact_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// AI Shop Admin Profile - admin-specific duty or contact extensions. Only for admin; distinct from core record. Used for compliance assignment, IP allowlist. Key: 1:1 to ai_shop_admins. Special: Compliance allows for optional/blank values in duty region, IP list.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_admin_profiles {
  //----
  // COLUMNS
  //----
  /// Primary key. Unique admin profile identity.
  id String @id @db.Uuid

  /// FK to ai_shop_admins.id, enforced unique (1:1).
  admin_id String @db.Uuid

  /// Compliance jurisdiction/region assigned to this admin. Optional.
  duty_region String?

  /// JSON array of approved IPs or CIDR ranges (for compliance); nil if unrestricted.
  ip_allowlist String?

  /// Backup/admin notification or escalation email; optional.
  contact_email String?

  /// Profile created timestamp.
  created_at DateTime @db.Timestamptz

  /// Last profile update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin_profile_fk ai_shop_admins @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@unique([admin_id])
  @@index([duty_region(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-03-products.prisma:
/// AI Shop Product - Implements requirements for product management as described in the requirements (core registration, management, AI-driven enrichment, and auditability). Strictly normalized (3NF), with options, variant, tags, inventory, images all separated. All edit/version history in ai_shop_product_snapshots. Business example: a seller creates a new product for sale. Key relationships: owned by seller (FK), references category. Special: supports soft deletion and full audit trail.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_products {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique product record identifier.
  id String @id @db.Uuid

  /// Belonged seller's {@link ai_shop_sellers.id}. Each product belongs to a seller, enforcing business accountability and permissions.
  ai_shop_seller_id String @db.Uuid

  /// Category assignment for product (requirement: catalog classification). Normalized FK to ai_shop_categories.
  category_id String @db.Uuid

  /// Product name/title. Implements requirement for registration. Maintains 3NF—text is stored here, not duplicated. Example: 'Eco Bag Large'.
  name String

  /// Product description (rich text/HTML/markdown). Implements content display, AI enrichment. Example: 'A stylish eco bag with spacious main compartment.'
  description String

  /// Current product status. Enum: 'active','inactive','draft','suspended','deleted'. Controls visibility. Example: 'active'.
  status String

  /// Creation timestamp. Used for audit, analytics. Maintains 3NF.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for audit and analytics.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp; NULL if active. For compliance and audit. Optional.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_products_seller_id ai_shop_sellers @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  fk_ai_shop_products_category_id ai_shop_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)

  ai_shop_product_variants ai_shop_product_variants[]
  ai_shop_product_snapshots ai_shop_product_snapshots[]
  ai_shop_product_images ai_shop_product_images[]
  ai_shop_product_tags ai_shop_product_tags[]
  ai_shop_cart_items ai_shop_cart_items[]
  ai_shop_order_items ai_shop_order_items[]
  ai_shop_inquiries ai_shop_inquiries[]
  ai_shop_reviews ai_shop_reviews[]
  ai_shop_favorites_products ai_shop_favorites_products[]

  @@unique([ai_shop_seller_id, name])
  @@index([category_id])
  @@index([status])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product Variant - Implements support for multi-option/variant combo SKUs, as required for e-commerce product management. Example: Red-Large variant of a product. Maintains 3NF by holding only atomic data for SKU identification and linkage to parent product. Key relationship: belongs to exactly one product (FK). Example: Variant for bag in red, size L.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_product_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product reference {@link ai_shop_products.id}. Each variant links to its owner product.
  ai_shop_product_id String @db.Uuid

  /// Stock-Keeping Unit for logistics/integration. Must be unique for product+variant combo. Example: 'SKU-BAG-RED-L'.
  sku String

  /// Atomic string encoding of option combination (e.g., 'Color:Red;Size:L').
  option_combo String

  /// Barcode (EAN/UPC/QR) for scanning/inventory. Example: '8809876543210'. Nullable, not always required.
  barcode String?

  /// Whether this variant can be sold. Example: true.
  is_active Boolean

  //----
  // RELATIONS
  //----
  fk_ai_shop_product_variants_product_id ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)

  ai_shop_inventories ai_shop_inventories?
  ai_shop_cart_items ai_shop_cart_items[]
  ai_shop_order_items ai_shop_order_items[]

  @@unique([ai_shop_product_id, sku])
  @@index([ai_shop_product_id])
  @@index([sku])
  @@index([option_combo(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Inventory - Tracks the stock for each product variant, enabling inventory management, restock alerting, and audit trail. Strictly 3NF: one inventory per variant, all adjustments logged externally. Relationships: belongs to seller (FK), belongs to variant (1-1, unique). Example: stock of 25 items for SKU-RED-L.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_inventories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Product variant for this inventory item - FK to {@link ai_shop_product_variants.id}. 1:1 unique join.
  ai_shop_product_variant_id String @db.Uuid

  /// Seller owning this inventory record (for audit/control) {@link ai_shop_sellers.id}.
  ai_shop_seller_id String @db.Uuid

  /// Current stock quantity for this variant. Example: 10 units.
  stock Int @db.Integer

  /// Stock threshold at which restock alert triggers. Example: 3.
  restock_threshold Int @db.Integer

  /// Rate of sales for this variant per day/week/month. Used for AI-driven analytics. Example: 2.45 units/day.
  turnover_rate Float? @db.DoublePrecision

  /// Inventory record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp for audit/analytics.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp. Null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_inventories_variant_id ai_shop_product_variants @relation(fields: [ai_shop_product_variant_id], references: [id], onDelete: Cascade)
  fk_ai_shop_inventories_seller_id ai_shop_sellers @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_product_variant_id])
  @@index([ai_shop_seller_id])
  @@index([created_at])
}

/// Product Snapshot - Provides versioning and full edit/audit traceability for compliance, rollback, and business analytics. Strictly normalized: each snapshot records all atomic fields, with no denormalized data. Snapshots are linked to a product and timestamped. Example: reverting product to previous content after mistake or dispute. Key relationship: belongs to a product.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_product_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product for this snapshot (FK to ai_shop_products.id).
  ai_shop_product_id String @db.Uuid

  /// Name of product as of this snapshot, for rollback and audit. Example: 'Eco Bag Large'.
  name String

  /// Product description as of this snapshot, for audit trail. Strictly atomic for rollback. Example: 'A stylish eco bag with spacious main compartment.'
  description String

  /// Category at snapshot time. Used for rollback and compliance tracking.
  category_id String @db.Uuid

  /// Product status at this snapshot state (e.g., 'active').
  status String

  /// Snapshot creation timestamp, not product creation date.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this snapshot record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_product_snapshots_product_id ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_product_id, created_at])
  @@index([ai_shop_product_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product Images - Stores and organizes product images for gallery use, with URI, alt text, and gallery order/position. Strictly 3NF. Each image references a single product. Example: Main image for 'Eco Bag'.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_product_images {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product for this image (FK to ai_shop_products.id).
  ai_shop_product_id String @db.Uuid

  /// URI or location of the image file. Example: 'https://cdn.ai-shop.com/images/bag1.jpg'.
  image_uri String @db.VarChar(80000)

  /// Alt text for image accessibility compliance.
  alt_text String

  /// Gallery index/position in image ordering. Example: 1.
  position Int @db.Integer

  //----
  // RELATIONS
  //----
  fk_ai_shop_product_images_product_id ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_product_id, position])
  @@index([ai_shop_product_id])
  @@index([alt_text(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product Tag - Logical assignment of search/tag labels to products. Tags are atomic labels for search/AI-driven user experience and cross-sell. Strictly 3NF—no derived summaries or denormalized aggregates. Each record is a product-tag association, with unique constraint. Example: Tag on 'Eco Bag' as 'eco-friendly'.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_product_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Product this tag is assigned to (FK to ai_shop_products.id).
  ai_shop_product_id String @db.Uuid

  /// Atomic tag label. Example: 'eco-friendly'.
  tag_text String

  /// When the tag was created.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_product_tags_product_id ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_product_id, tag_text])
  @@index([created_at])
  @@index([tag_text(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product Import Log - Tracks all bulk import or batch product registration events. Used for audit, error tracking, and integration. Strictly normalized with explicit fields only. Key relationship: references seller of the import operation. Example: import of 100 SKUs from csv.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_product_import_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller who performed import event (FK to ai_shop_sellers.id).
  ai_shop_seller_id String @db.Uuid

  /// When the import completed.
  imported_at DateTime @db.Timestamptz

  /// URI to source batch file or import artifact.
  source_file String @db.VarChar(80000)

  /// Number of products handled in the import event.
  record_count Int @db.Integer

  /// Import operation status. Enum: 'pending','completed','failed'.
  status String

  /// Import failure or error reason; nullable, only populated on error.
  error_message String?

  //----
  // RELATIONS
  //----
  fk_ai_shop_product_import_logs_seller_id ai_shop_sellers @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_seller_id, imported_at])
  @@index([status])
  @@index([imported_at])
}

schemas.schema-04-bulletin.prisma:
/// Bulletin Board Posts - Implements user-generated, AI-moderated, and versioned board post requirements. Only core bulletin board content, media, and version histories handled via separate tables for strict normalization. Auditable and allows complex moderation and attribution.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to author customer. Nullable if authored by seller or admin. Enables polymorphic author referencing (customer).
  ai_shop_customer_id String? @db.Uuid

  /// FK to author seller. Nullable if authored by customer or admin. Enables polymorphic author referencing (seller).
  ai_shop_seller_id String? @db.Uuid

  /// FK to author admin. Nullable if authored by customer or seller. Enables polymorphic author referencing (admin).
  ai_shop_admin_id String? @db.Uuid

  /// FK to ai_shop_channels. Post is published to a channel/shopfront/section.
  channel_id String @db.Uuid

  /// Post title (summary): e.g. "Store Policy Update"
  title String

  /// Full post body (rich text, markdown, or plain).
  body String

  /// Type of authoring role: 'customer', 'seller', or 'admin'.
  role_type String

  /// Post status: draft/published/hidden/deleted.
  status String

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_posts_customer ai_shop_customers? @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_ai_shop_posts_seller ai_shop_sellers? @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  fk_ai_shop_posts_admin ai_shop_admins? @relation(fields: [ai_shop_admin_id], references: [id], onDelete: Cascade)
  fk_ai_shop_posts_channel ai_shop_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)

  ai_shop_post_comments ai_shop_post_comments[]
  ai_shop_post_attachments ai_shop_post_attachments[]
  ai_shop_post_snapshots ai_shop_post_snapshots[]
  ai_shop_post_recommendations ai_shop_post_recommendations[]
  ai_shop_post_reports ai_shop_post_reports[]
  ai_shop_moderation_actions ai_shop_moderation_actions[]

  @@index([ai_shop_customer_id])
  @@index([ai_shop_seller_id])
  @@index([ai_shop_admin_id])

  @@unique([channel_id, title])
  @@index([created_at])
  @@index([status])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Bulletin Board Comments - Supports infinite reply-threading, hierarchical/parent-child structure, and deep moderation. Authors are polymorphic (customer, seller, admin), attachments in separate table. Fully normalized for audit and compliance.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_post_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to ai_shop_posts. Each comment belongs to a post.
  post_id String @db.Uuid

  /// FK to customer author. Nullable for seller or admin authorship; used for polymorphic referencing (customer).
  ai_shop_customer_id String? @db.Uuid

  /// FK to seller author. Nullable for customer or admin authorship; used for polymorphic referencing (seller).
  ai_shop_seller_id String? @db.Uuid

  /// FK to admin author. Nullable for customer or seller authorship; used for polymorphic referencing (admin).
  ai_shop_admin_id String? @db.Uuid

  /// Self-referencing FK to ai_shop_post_comments (threaded replies). Null if root.
  parent_id String? @db.Uuid

  /// Comment content. Atomic, normalized.
  body String

  /// Type of author (customer/seller/admin).
  role_type String

  /// Timestamp of comment creation.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last edit/mod.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_post_comments_post ai_shop_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_comments_customer ai_shop_customers? @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_comments_seller ai_shop_sellers? @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_comments_admin ai_shop_admins? @relation(fields: [ai_shop_admin_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_comments_parent ai_shop_post_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_shop_post_comments[] @relation("recursive")
  ai_shop_comment_attachments ai_shop_comment_attachments[]
  ai_shop_moderation_actions ai_shop_moderation_actions[]

  @@index([ai_shop_customer_id])
  @@index([ai_shop_seller_id])
  @@index([ai_shop_admin_id])
  @@index([parent_id])

  @@index([post_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Attachments - File metadata for media/files attached to posts. Physical content referenced by ai_shop_files; only metadata is here. Strict 3NF.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_post_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to ai_shop_posts.
  post_id String @db.Uuid

  /// FK to ai_shop_files (physical file location).
  file_id String @db.Uuid

  /// Display name (e.g., image1.jpg)
  name String

  /// Attachment MIME/type or category.
  type String

  /// File size (bytes).
  size Int @db.Integer

  //----
  // RELATIONS
  //----
  fk_ai_shop_post_attachments_post ai_shop_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_attachments_file ai_shop_files @relation(fields: [file_id], references: [id], onDelete: Cascade)

  @@index([file_id])

  @@index([post_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Snapshots - History/audit of post edits & state changes. Each version is immutable and ties to the post and author at edit time.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_post_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to ai_shop_posts (which post is versioned).
  post_id String @db.Uuid

  /// FK to author customer. Nullable; supports polymorphic referencing (customer).
  ai_shop_customer_id String? @db.Uuid

  /// FK to author seller. Nullable; supports polymorphic referencing (seller).
  ai_shop_seller_id String? @db.Uuid

  /// FK to author admin. Nullable; supports polymorphic referencing (admin).
  ai_shop_admin_id String? @db.Uuid

  /// Title at this version.
  title String

  /// Body/content at this version.
  body String

  /// Role (customer/seller/admin) at snapshot time.
  role_type String

  /// Post status at time of version.
  status String

  /// Reason for versioning (edit/moderation).
  snapshot_reason String

  /// Timestamp of version creation.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_post_snapshots_post ai_shop_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_snapshots_customer ai_shop_customers? @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_snapshots_seller ai_shop_sellers? @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_snapshots_admin ai_shop_admins? @relation(fields: [ai_shop_admin_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_customer_id])
  @@index([ai_shop_seller_id])
  @@index([ai_shop_admin_id])

  @@index([post_id, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Recommendations - AI-powered or rule-based post recommendations and personalization tracking. 3NF: All references external, no denormalization.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_post_recommendations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to ai_shop_posts (recommended post).
  post_id String @db.Uuid

  /// FK to ai_shop_customers for personalized (customer) recommendations. Nullable for global or seller targeting.
  ai_shop_customer_id String? @db.Uuid

  /// FK to ai_shop_sellers for seller-personalized recommendations. Nullable; for non-seller/customer targeting.
  ai_shop_seller_id String? @db.Uuid

  /// Audience type (e.g., customer, seller, global).
  target_type String

  /// Why recommended (AI, trending, campaign, etc).
  reason String

  /// When recommended.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_post_recommendations_post ai_shop_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_recommendations_customer ai_shop_customers? @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_recommendations_seller ai_shop_sellers? @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)

  @@index([post_id])
  @@index([ai_shop_customer_id])
  @@index([ai_shop_seller_id])

  @@index([target_type, created_at])
}

/// Post Reports - Stores user-submitted (customer, seller, admin) reports against posts for abuse/toxicity audits and moderation workflow. Strict normalization/audit. Links to moderation-actions table if addressed.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_post_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to ai_shop_posts (target post).
  post_id String @db.Uuid

  /// FK to customer reporter. Nullable for seller or admin reporters.
  ai_shop_customer_id String? @db.Uuid

  /// FK to seller reporter. Nullable for customer or admin reporters.
  ai_shop_seller_id String? @db.Uuid

  /// FK to admin reporter. Nullable for customer or seller reporters.
  ai_shop_admin_id String? @db.Uuid

  /// FK to moderation action record (may be null if no action yet).
  moderation_action_id String? @db.Uuid

  /// Reporter-provided reason for report.
  reason String

  /// Timestamp of report creation.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_post_reports_post ai_shop_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_reports_customer ai_shop_customers? @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_reports_seller ai_shop_sellers? @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_reports_admin ai_shop_admins? @relation(fields: [ai_shop_admin_id], references: [id], onDelete: Cascade)
  fk_ai_shop_post_reports_action ai_shop_moderation_actions? @relation(fields: [moderation_action_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_customer_id])
  @@index([ai_shop_seller_id])
  @@index([ai_shop_admin_id])
  @@index([moderation_action_id])

  @@index([post_id, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Comment Attachments - File metadata for files/media attached to comments. Keeps comment table normalized and references ai_shop_files.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_comment_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to ai_shop_post_comments (parent comment).
  comment_id String @db.Uuid

  /// FK to ai_shop_files (underlying blob).
  file_id String @db.Uuid

  /// Attachment display name.
  name String

  /// Attachment type/MIME/type or class.
  type String

  /// Size in bytes.
  size Int @db.Integer

  //----
  // RELATIONS
  //----
  fk_ai_shop_comment_attachments_comment ai_shop_post_comments @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  fk_ai_shop_comment_attachments_file ai_shop_files @relation(fields: [file_id], references: [id], onDelete: Cascade)

  @@index([file_id])

  @@index([comment_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderation Actions - Tracks all moderation responses by admins/system/AI. Tied to posts, comments, and admin records for audit, denormalized only for audit IDs. Strict 3NF organization.
///
/// @namespace Bulletin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to the admin who issued the action.
  moderator_id String @db.Uuid

  /// FK to ai_shop_posts (if applicable, nullable for comment-moderation-only).
  post_id String? @db.Uuid

  /// FK to ai_shop_post_comments (nullable if post-only action).
  comment_id String? @db.Uuid

  /// Type of moderation, e.g., 'hide','delete','warn','restore'.
  action_type String

  /// Why the action was taken.
  reason String

  /// When the action took effect.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_moderation_actions_moderator ai_shop_admins @relation(fields: [moderator_id], references: [id], onDelete: Cascade)
  fk_ai_shop_moderation_actions_post ai_shop_posts? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  fk_ai_shop_moderation_actions_comment ai_shop_post_comments? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  ai_shop_post_reports ai_shop_post_reports[]

  @@index([moderator_id])
  @@index([post_id])
  @@index([comment_id])

  @@index([created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-05-carts.prisma:
/// Shopping Cart Entity - Implements the persistent cart requirement from the Cart and Order System document (Section 4, Functional Requirements #1, #3).
///
/// This model represents a logical shopping cart associated primarily with a customer or a guest session. Its business purpose is to enable the platform to store a user's intended purchases across sessions, devices, and authentication states. It ensures 3NF normalization by storing only the cart container and its metadata; specific cart item details are normalized into ai_shop_cart_items. For example, when a customer adds products to their shopping cart, this entity records the top-level cart record, trackable by customer_id or cart_session_id.
///
/// Key relationships: Links to ai_shop_cart_sessions (if unauthenticated), and to ai_shop_customers (for authenticated users; foreign key to be defined from Actors schema). Maintains audit fields and status for cart lifecycle (active, abandoned, converted, etc).
/// Special behaviors: Cart is unique to either a customer or a session, never both, supporting both registered and guest flows.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_carts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each shopping cart.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shop_customers.id}. Nullable for guest carts. This links a shopping cart directly to a registered customer account for persistent, cross-device cart experience.
  ai_shop_customer_id String? @db.Uuid

  /// Belonged cart session's {@link ai_shop_cart_sessions.id}. Used for unauthenticated/guest carts.
  ai_shop_cart_session_id String? @db.Uuid

  /// Cart status flag - Implements the requirement for lifecycle tracking (active, abandoned, converted). Business meaning: tracks the primary cart state for abandonment processing and analytic triggers. Normalized here as a single atomic value. E.g., 'active', 'abandoned'.
  status String

  /// Cart creation timestamp. Used for audit trails and tracking cart staleness/abandonment for compliance and customer service. 3NF-compliant atomic timestamp.
  created_at DateTime @db.Timestamptz

  /// Cart last updated timestamp. Enables precise cart lifecycle management, normalization preserved.
  updated_at DateTime @db.Timestamptz

  /// Timestamp of when the cart was considered abandoned. Implements compliance and business abandonment requirements. Nullable as only set when cart is abandoned.
  abandoned_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_shop_customers? @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  cart_session ai_shop_cart_sessions? @relation(fields: [ai_shop_cart_session_id], references: [id], onDelete: Cascade)

  ai_shop_cart_items ai_shop_cart_items[]
  ai_shop_orders ai_shop_orders[]

  @@unique([ai_shop_customer_id])
  @@unique([ai_shop_cart_session_id])
  @@index([created_at])
  @@index([updated_at])
  @@index([status])
}

/// Shopping Cart Item Entity - Implements the normalized itemization requirement from Cart and Order System document (Functional Requirements #1, #3, #4).
///
/// This entity stores each product/variant line in a shopping cart, supporting full 3NF normalization. Business purpose: allows for precise separation of cart container and contained product selections. For example, each entry represents a single SKU/variant the customer intends to buy, with quantity and option/variant references.
///
/// Key relationships: Belongs to ai_shop_carts, references ai_shop_products and ai_shop_product_variants (from Products schema) to ensure referential integrity for catalog links. Normalized: NO product names/prices stored here. Example usage: add-to-cart API inserts a record per selected product variant, quantity, and options. Special behaviors: Each cart can have many items, each item unique by product/variant constraints.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_cart_items {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each cart item.
  id String @id @db.Uuid

  /// Belonged cart's {@link ai_shop_carts.id}. Links item to its parent cart for proper containment and lifecycle management.
  ai_shop_cart_id String @db.Uuid

  /// Product reference's {@link ai_shop_products.id}. Enforces product-level referential integrity. Normalized - only stores reference, not product data.
  ai_shop_product_id String @db.Uuid

  /// Product variant reference's {@link ai_shop_product_variants.id}. Ensures atomic relationship at SKU/variant granularity. No denormalized attribute data.
  ai_shop_product_variant_id String @db.Uuid

  /// Quantity of the product variant requested. Implements the atomic, normalized representation of product choices. Always ≥ 1. E.g., user selects 2 of a certain size/color.
  quantity Int @db.Integer

  /// When the cart item was added. Business purpose: enables time-based cart, inventory, and promotional analytics. Maintains normalization as atomic value.
  added_at DateTime @db.Timestamptz

  /// Last update timestamp for cart item. Useful for tracking changes (e.g., quantity updates). Still atomic and normalized.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart ai_shop_carts @relation(fields: [ai_shop_cart_id], references: [id], onDelete: Cascade)
  product ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)
  product_variant ai_shop_product_variants @relation(fields: [ai_shop_product_variant_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_product_id])
  @@index([ai_shop_product_variant_id])

  @@unique([ai_shop_cart_id, ai_shop_product_id, ai_shop_product_variant_id])
  @@index([ai_shop_cart_id])
  @@index([added_at])
  @@index([quantity])
}

/// Cart Session Entity - Addresses the session-linked cart requirement from Cart and Order System (Functional Requirement #1 and architectural needs).
///
/// Business purpose: enables persistent cart storage for unauthenticated/guest users using a session-unique token. Maintains normalization by only recording the link to the guest session. When a user logs in, their session cart can be migrated to their account cart. For example, a new visitor adds items to a cart and is tracked via this record until authentication. Audit trail fields enable lifecycle and analytic monitoring.
///
/// Key relationships: Optionally linked to ai_shop_carts (1:1), not directly to products or customers. Used for session-based cart flows. Special behaviors: Carts can be migrated/merged between guest sessions and user accounts based on business rules.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_cart_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this cart session.
  id String @id @db.Uuid

  /// Unique session token issued to guest/unregistered users to identify cart sessions. Implements guest cart persistence. Atomic value; not reused or denormalized.
  session_token String

  /// Creation time for the cart session. Audit/compliance requirement.
  created_at DateTime @db.Timestamptz

  /// Last update time for the session's activity/lifecycle. Enables analysis and cart synchronization.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shop_carts ai_shop_carts?

  @@unique([session_token])
  @@index([created_at])
  @@index([updated_at])
}

schemas.schema-06-orders.prisma:
/// Order entity - This implements the primary order management requirement from the Cart and Order System requirements. Captures the full business-to-customer transaction lifecycle, including customer linkage, cart association, seller involvement, pricing, and order audit. 3NF compliance: Only atomic, normalized data (no pre-calculated totals). For example, when a customer checks out a cart, an ai_shop_orders record is created with all relevant FK links. Key relationships: Linked to ai_shop_customers, ai_shop_carts, ai_shop_sellers, and item, delivery, refund entities.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shop_customers.id}
  ai_shop_customer_id String @db.Uuid

  /// Seller's {@link ai_shop_sellers.id} for single-seller orders, or main seller in multi-seller scenario
  ai_shop_seller_id String @db.Uuid

  /// Associated cart's {@link ai_shop_carts.id} for order provenance
  ai_shop_cart_id String @db.Uuid

  /// Order human-readable identifier - Implements traceability for the business and customers. 3NF: not derived from other columns, strictly assigned at order creation. E.g. 'ORD20240722-0001'.
  order_number String

  /// Current order business status (e.g., pending, paid, shipped, delivered, cancelled, refunded) - Implements state management. Not derived. Usage: for process control and audit.
  status String

  /// Timestamp when order was placed - Implements audit/compliance requirements. Not derived data. Used to track order creation moment.
  submitted_at DateTime @db.Timestamptz

  /// Last updated timestamp - For auditing order state progression. Not derived; is updated by workflow actions.
  updated_at DateTime @db.Timestamptz

  /// Selected payment method code (e.g., 'card', 'deposit', 'coupon'). Fulfills checkout and compliance requirement. Not derived from other entities.
  payment_method String

  /// Customer's memo for the order (e.g., delivery instructions) - Direct input, atomic, not derived.
  customer_memo String?

  /// Internal admin memo about the order - 3NF: for audit/admin use only, not shown externally. Input only, not derived.
  admin_note String?

  /// Soft deletion flag: timestamp if deleted, null otherwise. For audit and compliance, enables logical deletes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  seller ai_shop_sellers @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  cart ai_shop_carts @relation(fields: [ai_shop_cart_id], references: [id], onDelete: Cascade)

  ai_shop_order_items ai_shop_order_items[]
  ai_shop_order_status_histories ai_shop_order_status_histories[]
  ai_shop_order_refunds ai_shop_order_refunds[]
  ai_shop_order_abandonments ai_shop_order_abandonments[]
  ai_shop_order_deliveries ai_shop_order_deliveries[]
  ai_shop_coupon_assignments ai_shop_coupon_assignments[]
  ai_shop_deposits ai_shop_deposits[]
  ai_shop_mileages ai_shop_mileages[]
  ai_shop_donation_coupons ai_shop_donation_coupons[]

  @@index([ai_shop_cart_id])

  @@unique([order_number])
  @@index([ai_shop_customer_id, submitted_at])
  @@index([status])
  @@index([ai_shop_seller_id, submitted_at])
}

/// Order item detail - Implements the order line-items requirement from the Cart and Order System plan. Each row represents a distinct item within an order (SKU-level). Fully normalized (3NF): no derived subtotals or aggregates; each field corresponds directly to atomic input or reference. Used, for example, to list each purchased product with its variant, quantity, and price at purchase time. Key relationships: Foreign keys to ai_shop_orders and ai_shop_products/variants.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_order_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent order's {@link ai_shop_orders.id} - Required for item linkage.
  ai_shop_order_id String @db.Uuid

  /// Purchased product's {@link ai_shop_products.id} - 3NF; atomic reference for business reporting.
  ai_shop_product_id String @db.Uuid

  /// Variant of the product's {@link ai_shop_product_variants.id}. Enables SKU-level granularity and atomic normalization.
  ai_shop_product_variant_id String? @db.Uuid

  /// Snapshot of the product name at purchase. Implements audit/traceability. Not derived; direct input. Example: 'AI Smart Speaker v2'.
  product_name String

  /// Optional: Variant display name for audit. Not derived; direct.
  variant_name String?

  /// Quantity of this product/variant purchased.
  quantity Int @db.Integer

  /// Unit price at time of purchase (after discounts, if any). Fulfills audit and compliance; no calculations, atomic only.
  unit_price Float @db.DoublePrecision

  /// Currency code (e.g., 'USD', 'KRW') at sale time. Required for international operations; not derived.
  currency String

  /// Memo field for seller-side item note. Not derived; audit use. Example: 'Special packing'.
  seller_memo String?

  //----
  // RELATIONS
  //----
  order ai_shop_orders @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)
  product ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)
  product_variant ai_shop_product_variants? @relation(fields: [ai_shop_product_variant_id], references: [id], onDelete: Cascade)

  ai_shop_return_requests ai_shop_return_requests[]
  ai_shop_order_deliveries ai_shop_order_deliveries[]

  @@index([ai_shop_product_variant_id])

  @@unique([ai_shop_order_id, ai_shop_product_id, ai_shop_product_variant_id])
  @@index([ai_shop_order_id])
  @@index([ai_shop_product_id])
}

/// Order state change log - Implements the audit/compliance snapshot from requirements: logs every change in ai_shop_orders.status. Maintains full normalized snapshot history. For example, a new row is added whenever the order status transitions (e.g., from 'pending' to 'paid'). Key relationships: Foreign key to ai_shop_orders. Special behaviors: Immutable records, always append-only.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_order_status_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the affected {@link ai_shop_orders.id}. For access path and integrity.
  ai_shop_order_id String @db.Uuid

  /// Optional reference to admin who performed the update. For compliance and traceability ({@link ai_shop_admins.id}).
  changed_by_admin_id String? @db.Uuid

  /// Previous status value - For audit trail, normalization 3NF: not derived.
  from_status String

  /// New status value - For audit trail.
  to_status String

  /// Timestamp of change event. Not derived; audit evidence. Atomic property.
  changed_at DateTime @db.Timestamptz

  /// Optional admin/editor reason for status change. Fulfills requirement for business auditing. Not derived.
  change_reason String?

  //----
  // RELATIONS
  //----
  order ai_shop_orders @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)
  changed_by_admin ai_shop_admins? @relation(fields: [changed_by_admin_id], references: [id], onDelete: Cascade)

  @@index([changed_by_admin_id])

  @@index([ai_shop_order_id])
}

/// Order refund request entity - Fulfills the requirement for explicit tracking of refund requests and processing from the requirements analysis. 3NF compliance: only atomic, factual attributes are stored for each refund. Used, for instance, when a buyer requests a refund for an order item. Key relationships: FK to ai_shop_orders.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_order_refunds {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Refunded order's {@link ai_shop_orders.id}. For traceability and workflow enforcement.
  ai_shop_order_id String @db.Uuid

  /// FK to customer who requested refund ({@link ai_shop_customers.id}). Maintains normalization and compliance, enforces audit trail.
  requested_by_customer_id String @db.Uuid

  /// Business reason stated for refund request - Implements audit and fulfillment requirements. Atomic value, never derived.
  refund_reason String

  /// Status of the refund process (e.g., requested, approved, denied, completed). For business workflow management and normalization.
  refund_status String

  /// When refund was submitted. Used for compliance/audit, not derived.
  requested_at DateTime @db.Timestamptz

  /// When refund was processed/closed. Null if pending.
  processed_at DateTime? @db.Timestamptz

  /// Admin-side notes on the refund - Enforces business transparency. Input only, not derived.
  admin_note String?

  //----
  // RELATIONS
  //----
  order ai_shop_orders @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)
  requested_by_customer ai_shop_customers @relation(fields: [requested_by_customer_id], references: [id], onDelete: Cascade)

  @@index([requested_by_customer_id])

  @@index([ai_shop_order_id])
}

/// Order item return request entity - Implements the requirement for customer-initiated product returns, maintaining normalized row-per-return structure as required by 3NF. For example, created when a customer requests a return or exchange for an order item. Key relationships: FK to ai_shop_order_items and ai_shop_customers. Return lifecycle is managed at item level for audit precision and inventory control.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_return_requests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Returned order item ({@link ai_shop_order_items.id}). Maintains atomic normalization.
  ai_shop_order_item_id String @db.Uuid

  /// FK to requesting customer ({@link ai_shop_customers.id}). Clarifies provenance, audit, and compliance.
  requested_by_customer_id String @db.Uuid

  /// Text of the customer's return reason - Implements the workflow initiation element of return processing. 3NF, atomic, never derived.
  return_reason String

  /// Return workflow status (e.g., requested, approved, denied, completed, received). Used in process control. Never derived, atomic.
  return_status String

  /// When the return was requested. Used for workflow and audit compliance.
  requested_at DateTime @db.Timestamptz

  /// When the return request was processed. Null if pending.
  processed_at DateTime? @db.Timestamptz

  /// Admin field for workflow notes and comments (input only, not derived). 3NF.
  admin_note String?

  //----
  // RELATIONS
  //----
  order_item ai_shop_order_items @relation(fields: [ai_shop_order_item_id], references: [id], onDelete: Cascade)
  requested_by_customer ai_shop_customers @relation(fields: [requested_by_customer_id], references: [id], onDelete: Cascade)

  @@index([requested_by_customer_id])

  @@index([ai_shop_order_item_id])
}

/// Abandoned order log - Implements the business requirement to track orders that were initiated but never completed (cart or payment abandoned). 3NF: Each abandonment event is atomic, one row per occurrence; no denormalized or summarized fields. Used to trigger automated retention offers, cart recovery, and behavioral analytics. Key relationships: FK to ai_shop_orders and ai_shop_customers for provenance and audit.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_order_abandonments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Abandoned order ({@link ai_shop_orders.id}). Required to link event and main order data.
  ai_shop_order_id String @db.Uuid

  /// FK to the customer who abandoned the order ({@link ai_shop_customers.id}). For reporting and behavioral analytics.
  ai_shop_customer_id String @db.Uuid

  /// When the abandonment was registered (cart closed, payment not completed, etc.). Business workflow trigger; atomic, not derived.
  abandoned_at DateTime @db.Timestamptz

  /// Business code for how/why the abandonment was recognized (e.g., 'timeout', 'payment_fail', 'customer_cancel', 'browser_exit'). Input only, atomic.
  detection_method String

  //----
  // RELATIONS
  //----
  order ai_shop_orders @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)
  customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_order_id])

  @@index([ai_shop_customer_id])
}

/// Order delivery workflow entity - Fulfills order delivery/logistics requirement from analysis. Each record reflects a delivery event associated with an order. 3NF normalized: one row per delivery event, all fields atomic. For example, created when a seller creates or updates a delivery for an order with shipment information. Key relationships: FK to ai_shop_orders and ai_shop_sellers. May also reference ai_shop_order_items if split delivery is supported (field is optional/null).
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_order_deliveries {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related order's {@link ai_shop_orders.id}. For context and access control.
  ai_shop_order_id String @db.Uuid

  /// Optionally links for split/partial deliveries ({@link ai_shop_order_items.id}); null for full-order deliveries.
  ai_shop_order_item_id String? @db.Uuid

  /// Delivery processing seller ({@link ai_shop_sellers.id}). Required for fulfillment audit trail.
  ai_shop_seller_id String @db.Uuid

  /// Delivery progress status (e.g., pending, ready, shipped, delivered, returned). For workflow and audit. Atomic only, not derived.
  delivery_status String

  /// Shipper's tracking/parcel number, never calculated. 3NF compliant.
  tracking_number String?

  /// Courier company/service code per business policy. For example, 'CJ', 'FEDEX'. Not derived, never aggregated.
  shipper_code String

  /// When parcel left warehouse/seller. Fulfills audit and workflow audit.
  shipped_at DateTime? @db.Timestamptz

  /// When parcel reached customer. Fulfills audit and customer care business requirements. Null if not delivered.
  delivered_at DateTime? @db.Timestamptz

  /// Seller-side memo on the delivery - input only, atomic, never derived.
  seller_memo String?

  /// Admin auditing/memo field, fully normalized.
  admin_note String?

  //----
  // RELATIONS
  //----
  order ai_shop_orders @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)
  order_item ai_shop_order_items? @relation(fields: [ai_shop_order_item_id], references: [id], onDelete: Cascade)
  seller ai_shop_sellers @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_order_item_id])
  @@index([ai_shop_seller_id])

  @@index([ai_shop_order_id])
  @@index([tracking_number])
}

schemas.schema-07-coupons.prisma:
/// Coupon entity - This implements the 'Digital Coupons & Campaign Codes' requirement from the Discount and Payment System requirements. Represents all coupons (single-use, multi-use, stackable or exclusive) available for promotional campaigns, targeted offers, or seller-specific deals. Maintains 3NF compliance. For example, a campaign might generate 10,000 unique coupon codes, all tracked here.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_coupons {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique coupon identifier for lifecycle management, audit, and traceability.
  id String @id @db.Uuid

  /// Related promotion's {@link ai_shop_promotions.id}. Nullable if coupon is not part of a campaign.
  ai_shop_promotion_id String? @db.Uuid

  /// Coupon code string (unique).
  code String

  /// Coupon type (e.g., 'single_use','multi_use','stackable','exclusive').
  type String

  /// Human-friendly explanation of the coupon.
  description String?

  /// Coupon validation start datetime.
  valid_from DateTime @db.Timestamptz

  /// Coupon expiration datetime.
  valid_until DateTime @db.Timestamptz

  /// Maximum total uses before expiration.
  max_uses Int? @db.Integer

  /// Maximum uses per customer.
  max_uses_per_customer Int? @db.Integer

  /// Minimum order amount for coupon redemption.
  min_purchase_amount Float? @db.DoublePrecision

  /// Absolute discount (e.g., $5 off) or null if only percent.
  discount_amount Float? @db.DoublePrecision

  /// Discount percent (e.g., 10.0 for 10%).
  discount_percent Float? @db.DoublePrecision

  /// Current activation status.
  is_active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  promotion ai_shop_promotions? @relation(fields: [ai_shop_promotion_id], references: [id], onDelete: Cascade)

  ai_shop_coupon_assignments ai_shop_coupon_assignments[]
  ai_shop_donation_coupons ai_shop_donation_coupons[]

  @@unique([code])
  @@index([ai_shop_promotion_id])
  @@index([valid_from, valid_until])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Coupon Assignment entity - Implements the requirement 'Assignment, Tracking, Usage Logging' for coupons. Tracks which customer (or entity) has received, claimed, or used a specific coupon. Maintains 3NF by separating assignment and usage from coupon definition. For example, a user redeeming a code will have a row here.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_coupon_assignments {
  //----
  // COLUMNS
  //----
  /// Primary Key for uniquely identifying each coupon assignment event.
  id String @id @db.Uuid

  /// Assigned coupon's {@link ai_shop_coupons.id}.
  ai_shop_coupon_id String @db.Uuid

  /// Assigned or claiming customer's {@link ai_shop_customers.id}.
  ai_shop_customer_id String @db.Uuid

  /// Order's {@link ai_shop_orders.id} where the coupon was applied.
  ai_shop_order_id String? @db.Uuid

  /// Timestamp when coupon assigned to customer.
  assigned_at DateTime @db.Timestamptz

  /// Nullable redemption timestamp.
  redeemed_at DateTime? @db.Timestamptz

  /// Assignment state ('assigned', 'redeemed', 'expired', etc.).
  state String

  //----
  // RELATIONS
  //----
  coupon ai_shop_coupons @relation(fields: [ai_shop_coupon_id], references: [id], onDelete: Cascade)
  customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  order ai_shop_orders? @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_coupon_id, ai_shop_customer_id])
  @@index([ai_shop_customer_id])
  @@index([ai_shop_order_id])
  @@index([state])
}

/// Promotion/Campaign entity - Implements the 'Promotion Campaign, Bulk Coupon Creation, and Event Management' requirements. Tracks all coupon campaigns, automatic promotions, manual or AI-driven sales events that govern coupon logic and presentation. Each campaign can generate multiple coupon codes linked via ai_shop_coupons.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_promotions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Each campaign/promotion's unique identifier.
  id String @id @db.Uuid

  /// Promotion title (e.g., 'Summer 2025 Campaign').
  name String

  /// Human-friendly explanation.
  description String?

  /// Promotion type ('bulk_coupon', 'auto_discount', 'event', etc.).
  type String

  /// Campaign start timestamp.
  start_at DateTime @db.Timestamptz

  /// Campaign end timestamp.
  end_at DateTime @db.Timestamptz

  /// Whether the campaign is enabled and visible.
  is_active Boolean

  /// Campaign creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for campaign.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shop_coupons ai_shop_coupons[]

  @@unique([name, start_at])
  @@index([start_at, end_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Deposit entity - Implements 'Customer/Seller Deposit Tracking and Balance Ledger'. Represents non-withdrawable or redeemable credits in the platform, viewable and manageable per-user. Maintains 3NF. For example, a single credit purchase transaction appears as a row in this table.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_deposits {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique deposit ledger entry.
  id String @id @db.Uuid

  /// Customer making the deposit.
  ai_shop_customer_id String @db.Uuid

  /// Seller beneficiary for this deposit (nullable).
  ai_shop_seller_id String? @db.Uuid

  /// Order associated with this deposit (nullable).
  ai_shop_order_id String? @db.Uuid

  /// Deposit line type: 'credit','debit','reward', etc.
  type String

  /// Deposit transaction amount.
  amount Float @db.DoublePrecision

  /// Optional transaction note.
  description String?

  /// Ledger entry creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  seller ai_shop_sellers? @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  order ai_shop_orders? @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_order_id])

  @@index([ai_shop_customer_id, created_at])
  @@index([ai_shop_seller_id, created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Mileage entity - This implements the 'Mileage Points Tracking' requirement for discount and loyalty. Tracks all atomic accrual or deduction transactions for the mileage (point, loyalty) system tied to a specific customer.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_mileages {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each mileage transaction entry.
  id String @id @db.Uuid

  /// Customer earning or spending mileage points.
  ai_shop_customer_id String @db.Uuid

  /// Order linked to mileage flow (earning/redeeming). Nullable.
  ai_shop_order_id String? @db.Uuid

  /// Mileage transaction type: 'earn','redeem','adjust','expire', etc.
  type String

  /// Change in mileage points (positive or negative).
  amount Int @db.Integer

  /// Optional note for the points event.
  description String?

  /// Transaction timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  order ai_shop_orders? @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_customer_id, created_at])
  @@index([ai_shop_order_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Donation Coupon entity - Implements the requirements for 'Donation-Linked Coupon Tracking' and compliance with charity-linked transactions. Represents specialized coupons whose use generates (or is funded by) charitable contributions. Normalized to atomic value and relationship per company compliance requirements.
///
/// @namespace Coupons
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_donation_coupons {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each donation-related coupon entry.
  id String @id @db.Uuid

  /// Coupon involved in the donation.
  ai_shop_coupon_id String @db.Uuid

  /// Customer who used the coupon (donor).
  ai_shop_customer_id String @db.Uuid

  /// Related order (if the donation is tied to a purchase). Nullable.
  ai_shop_order_id String? @db.Uuid

  /// Monetary value of donation linked to this coupon redemption.
  amount_donated Float @db.DoublePrecision

  /// Donation linkage type (e.g., 'seller_funded','platform_match','customer_opt_in').
  donation_type String

  /// Creation timestamp for audit trails and compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  coupon ai_shop_coupons @relation(fields: [ai_shop_coupon_id], references: [id], onDelete: Cascade)
  customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  order ai_shop_orders? @relation(fields: [ai_shop_order_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_order_id])

  @@index([ai_shop_coupon_id])
  @@index([ai_shop_customer_id])
}

schemas.schema-08-inquiries_reviews.prisma:
/// Inquiry Entity - Implements the core inquiry requirements from the AI Shop Inquiry and Review System requirements analysis (see ERD section). 
///
/// This model represents individual product or order inquiries written by customers. It is fully normalized with a direct relationship to the customer making the inquiry and optional linkage to a specific product. Maintains 3NF by only including inquiry-specific attributes; replies and moderation are handled in separate, related tables. Example: A customer submits a question about a product, tracked here for workflow, analytics, and future reference.
///
/// Key relationships: belongs to a customer (foreign key to ai_shop_customers) and may reference ai_shop_products. All replies, ratings, and moderation are tracked outside of this entity. 
/// Special behaviors: Each inquiry is immutable for audit logging, and moderation actions are independently tracked.
///
/// @namespace InquiriesReviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_inquiries {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each inquiry.
  id String @id @db.Uuid

  /// Referenced customer's {@link ai_shop_customers.id}. Indicates the customer who wrote this inquiry.
  ai_shop_customer_id String @db.Uuid

  /// Target product's {@link ai_shop_products.id} this inquiry is about, if any.
  ai_shop_product_id String? @db.Uuid

  /// Title of the inquiry - Implements requirement for clear subject line. This field provides a concise indicator of inquiry content for listing, search, and indexing.
  title String

  /// Inquiry content/body - Main question or statement posed by the customer. Normalized as atomic text.
  body String

  /// Inquiry status - Implements workflow requirement. Indicates open, resolved, or closed state, used in moderation and escalation flows. Example: 'open', 'answered', 'closed'.
  status String

  /// Timestamp when the inquiry was created. Required for audit trail and ordering.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update (if any). For mod tracking and data freshness monitoring. Null when never updated.
  updated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_inquiries_customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_ai_shop_inquiries_product ai_shop_products? @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)

  ai_shop_inquiry_replies ai_shop_inquiry_replies[]
  ai_shop_inquiry_moderations ai_shop_inquiry_moderations[]
  ai_shop_favorites_inquiries ai_shop_favorites_inquiries[]

  @@unique([ai_shop_customer_id, title])
  @@index([ai_shop_product_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Inquiry Reply Entity - Implements the need for threaded, multi-seller/admin/customer responses to inquiries per requirements and ERD. 
///
/// This model is 3NF compliant and stores individual replies to an inquiry, including support for nested replies (threading) via self-referencing parent_id. It allows both sellers and admins to engage customers transparently. 
///
/// Key relationships: References ai_shop_inquiries (parent inquiry), ai_shop_sellers, ai_shop_admins; supports hierarchy via parent_id for infinite threading. Usage example: Seller answers a question, followed by further clarification threads.
///
/// @namespace InquiriesReviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_inquiry_replies {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each reply.
  id String @id @db.Uuid

  /// Parent inquiry's {@link ai_shop_inquiries.id} this reply references.
  ai_shop_inquiry_id String @db.Uuid

  /// Seller user {@link ai_shop_sellers.id} who wrote the reply, if reply is from a seller.
  ai_shop_seller_id String? @db.Uuid

  /// Admin user {@link ai_shop_admins.id} who wrote the reply, if reply is from an admin.
  ai_shop_admin_id String? @db.Uuid

  /// Self-reference for threaded replies (parent reply). Allows for hierarchical, nested threading of responses.
  parent_id String? @db.Uuid

  /// Reply content/body - Core reply message. Implements business rule for atomic, auditable communication.
  body String

  /// Timestamp when this reply was made. For chronological ordering, moderation, and SLA measurement.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_inquiry_replies_inquiry ai_shop_inquiries @relation(fields: [ai_shop_inquiry_id], references: [id], onDelete: Cascade)
  fk_ai_shop_inquiry_replies_seller ai_shop_sellers? @relation(fields: [ai_shop_seller_id], references: [id], onDelete: Cascade)
  fk_ai_shop_inquiry_replies_admin ai_shop_admins? @relation(fields: [ai_shop_admin_id], references: [id], onDelete: Cascade)
  fk_ai_shop_inquiry_replies_parent ai_shop_inquiry_replies? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_shop_inquiry_replies[] @relation("recursive")

  @@index([ai_shop_seller_id])
  @@index([ai_shop_admin_id])
  @@index([parent_id])

  @@index([ai_shop_inquiry_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Review Entity - Implements the customer product review requirements (see Inquiry & Review requirements and ERD). 
///
/// This fully normalized model represents a single customer review on a product, with atomic fields for content, rating score, and extensive linkage to customer and product. Snapshots for moderation/history are tracked separately. 
///
/// Compliance: 3NF strictly maintained (no pre-aggregations/denormalizations). Usage example: Customer writes a review for a purchased product, which is then subject to moderation/rating workflows.
///
/// @namespace InquiriesReviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_reviews {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the review.
  id String @id @db.Uuid

  /// Customer {@link ai_shop_customers.id} who wrote the review.
  ai_shop_customer_id String @db.Uuid

  /// Product {@link ai_shop_products.id} being reviewed.
  ai_shop_product_id String @db.Uuid

  /// Review content/body. The normalized text of the review. Example: Customer's feedback.
  body String

  /// Star rating assigned by the customer. Integer value, typically 1-5. Enforces business logic for star-based rating systems.
  rating Int @db.Integer

  /// Moderation or publication status (e.g., 'pending', 'approved', 'rejected'). Used in system workflows to separate public/pending reviews.
  status String

  /// Timestamp when review is written. Supports analytics/audit trail.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last edit. Nullable if never updated.
  updated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_reviews_customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_ai_shop_reviews_product ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)

  ai_shop_review_moderations ai_shop_review_moderations[]
  ai_shop_review_ratings ai_shop_review_ratings[]

  @@unique([ai_shop_customer_id, ai_shop_product_id])
  @@index([ai_shop_product_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Review Moderation Record - Implements review moderation flow (see Inquiry & Review System acceptance criteria). Tracks all moderation actions, linking reviews, admins, and logs. 
///
/// Each moderation record is created per action and is fully normalized, separated from review content itself. Enables full audit, compliance tracing, and snapshotting.
///
/// Key relationships: References ai_shop_reviews (target), ai_shop_admins (actor/admin), and includes moderation decision, notes, and timestamp. Example: Admin flags or approves a review after AI or human check.
///
/// @namespace InquiriesReviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_review_moderations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique moderation action record.
  id String @id @db.Uuid

  /// Target review's {@link ai_shop_reviews.id}.
  ai_shop_review_id String @db.Uuid

  /// Admin actor {@link ai_shop_admins.id} who took moderation action.
  ai_shop_admin_id String @db.Uuid

  /// Moderation action ('approve', 'reject', 'flag'). Maps to business rules for platform compliance.
  action String

  /// Reason for moderation action. Ensures all actions are auditable and justified. Example: 'Spam', 'Abusive language'.
  reason String

  /// Timestamp of moderation action; ensures traceability and audit compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_review_moderations_review ai_shop_reviews @relation(fields: [ai_shop_review_id], references: [id], onDelete: Cascade)
  fk_ai_shop_review_moderations_admin ai_shop_admins @relation(fields: [ai_shop_admin_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_admin_id])

  @@index([ai_shop_review_id, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Review Helpful/Helpfulness Rating - Implements atomic, per-user (customer) ratings of reviews' helpfulness per requirements document.
///
/// Each record logs a single customer's upvote/downvote (e.g., 'helpful' or not) on a specific review, meeting requirements for engagement tracking and feedback loops. Enforces 3NF by storing only atomic user-review vote; any aggregation is handled externally. 
///
/// Key relationships: References ai_shop_reviews and ai_shop_customers for each vote instance. Example usage: Customer marks a review as 'helpful', supporting review ranking and display.
///
/// @namespace InquiriesReviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_review_ratings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique instance of review rating/vote.
  id String @id @db.Uuid

  /// Target review's {@link ai_shop_reviews.id} being rated.
  ai_shop_review_id String @db.Uuid

  /// Customer {@link ai_shop_customers.id} giving the helpfulness rating.
  ai_shop_customer_id String @db.Uuid

  /// Helpfulness indicator (true for helpful, false for not). Implements binary upvote/downvote pattern per requirements.
  helpful Boolean

  /// Timestamp when the helpfulness vote was registered. Enables feedback recency tracking and abuse mitigation.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_review_ratings_review ai_shop_reviews @relation(fields: [ai_shop_review_id], references: [id], onDelete: Cascade)
  fk_ai_shop_review_ratings_customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_customer_id])

  @@unique([ai_shop_review_id, ai_shop_customer_id])
  @@index([ai_shop_review_id])
}

/// Inquiry Moderation Record - Implements moderation tracking requirements for customer inquiries, meeting audit and platform compliance business imperatives.
///
/// Each record reflects a moderation action performed by an admin on a specific inquiry, separately from the inquiry content itself. 3NF is maintained by avoiding denormalized outcomes— snapshots and aggregate data managed elsewhere. 
///
/// Key relationships: Connects the moderated inquiry, the acting admin, and logs specific action/reason.
/// Example: An admin flags a question as inappropriate, records action and rationale for audit.
///
/// @namespace InquiriesReviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_inquiry_moderations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique moderation action instance.
  id String @id @db.Uuid

  /// Moderated inquiry's {@link ai_shop_inquiries.id}.
  ai_shop_inquiry_id String @db.Uuid

  /// Admin {@link ai_shop_admins.id} performing the moderation.
  ai_shop_admin_id String @db.Uuid

  /// Moderation action type (e.g., 'approve', 'flag', 'delete'). Mirrors business logic for workflow transitions.
  action String

  /// Justification for moderation action. Required for compliance/audit. Example: 'Off-topic', 'Spam', etc.
  reason String

  /// Timestamp of moderation action.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shop_inquiry_moderations_inquiry ai_shop_inquiries @relation(fields: [ai_shop_inquiry_id], references: [id], onDelete: Cascade)
  fk_ai_shop_inquiry_moderations_admin ai_shop_admins @relation(fields: [ai_shop_admin_id], references: [id], onDelete: Cascade)

  @@index([ai_shop_admin_id])

  @@index([ai_shop_inquiry_id, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-09-favorites.prisma:
/// Product favorites entity - Implements the favorites product feature from the "Favorites System" requirements document. Tracks a customer's favorited products, enabling AI-driven personalized sorting and management. Maintains strict 3NF normalization by keeping atomic relationships (favored product, owning customer) separate from business logic. For example, when a user favorites a product, a record is created here for audit trail and personalization.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_favorites_products {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the product favorite entry.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shop_customers.id}. Links favorite record to the owning customer. Enforces per-user favorite list for compliance and analytics.
  ai_shop_customer_id String @db.Uuid

  /// Favorited product's {@link ai_shop_products.id}. Identifies the specific product marked as favorite. Guarantees referential integrity and tracks product-specific favoriting activity.
  ai_shop_product_id String @db.Uuid

  /// Timestamp when the favorite was added. Implements audit trail and is required for analytics and compliance, ensuring full lifecycle traceability.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_favs_product_customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_favs_product_product ai_shop_products @relation(fields: [ai_shop_product_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_customer_id, ai_shop_product_id])
  @@index([ai_shop_customer_id])
  @@index([ai_shop_product_id])
  @@index([created_at])
}

/// Inquiry favorites entity - Implements feature for favoriting customer service/product inquiries. Allows users to bookmark inquiries (e.g. product Q&A, support tickets). Maintains 3NF by relating each favorite atomically to a customer and a single inquiry. For example, a seller may favorite a repeat FAQ for quick reference.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_favorites_inquiries {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the inquiry favorite entry.
  id String @id @db.Uuid

  /// Owner's {@link ai_shop_customers.id}. Links the favorite to the user for dashboard sorting and audit trails.
  ai_shop_customer_id String @db.Uuid

  /// Favorited inquiry's {@link ai_shop_inquiries.id}. Identifies the specific inquiry marked as favorite.
  ai_shop_inquiry_id String @db.Uuid

  /// Timestamp of favorite addition for auditing, sorting, and personalization.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_favs_inquiry_customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_favs_inquiry_inquiry ai_shop_inquiries @relation(fields: [ai_shop_inquiry_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_customer_id, ai_shop_inquiry_id])
  @@index([ai_shop_customer_id])
  @@index([ai_shop_inquiry_id])
  @@index([created_at])
}

/// Address favorites entity - Fulfills the requirement of favoriting frequently-used shipping or billing addresses. Lets customers quickly access preferred addresses for checkout. Maintains 3NF so that each favorite relates singularly to a customer and an address record with timestamped history. For example, during checkout, a user can select a saved favorite address.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_favorites_addresses {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the address favorite entry.
  id String @id @db.Uuid

  /// Owner's {@link ai_shop_customers.id}. Establishes which user owns this address favorite.
  ai_shop_customer_id String @db.Uuid

  /// Reference to user's {@link ai_shop_customer_profiles.id}. Points to the address profile, separating favoriting logic from profile data for normalization.
  ai_shop_profile_id String @db.Uuid

  /// Timestamp for when this favorite entry was created, for analytics and sorting.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_favs_address_customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)
  fk_favs_address_profile ai_shop_customer_profiles @relation(fields: [ai_shop_profile_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_customer_id, ai_shop_profile_id])
  @@index([ai_shop_customer_id])
  @@index([ai_shop_profile_id])
  @@index([created_at])
}

/// Notification favorites entity - Implements the feature for favoriting platform/campaign notifications. Allows users to save important notifications for future reference (promo or transactional alerts). Achieves 3NF by keeping notification favoriting records atomic, separated from notification content or delivery log. For example, a notification about a sale can be favorited and shown in a priority section.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shop_favorites_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the notification favorite entry.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shop_customers.id}. Indicates the favoriting user, for tracking and personalization.
  ai_shop_customer_id String @db.Uuid

  /// ID of the notification favorited. Business semantic: References the favorited notification. No enforced FK because ai_shop_notifications table does not exist.
  ai_shop_notification_id String @db.Uuid

  /// Datetime for when the favorite was added. Used for sorting, auditing, and personalization.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_favs_notification_customer ai_shop_customers @relation(fields: [ai_shop_customer_id], references: [id], onDelete: Cascade)

  @@unique([ai_shop_customer_id, ai_shop_notification_id])
  @@index([ai_shop_customer_id])
  @@index([ai_shop_notification_id])
  @@index([created_at])
}

