import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for batch listing/searching aiShopChannel entities with admin authorization,
 * verifying filter, search, sort, pagination, and permission controls.
 *
 * Business Context:
 * Admin users must efficiently retrieve, query, and manage shop channel data for configuration and monitoring.
 * Batch API supports full-text search, code and status filters, sorting, and robust pagination. Only admin roles may access.
 *
 * Test Workflow:
 * 1. Create several aiShopChannel entries with distinct codes, names, statuses, and sort_orders.
 * 2. List all channels; validate presence, total, and page meta; assert type safety for every row.
 * 3. Search by code substring (partial), check results match expectation, type assert rows.
 * 4. Filter by enabled status (true/false), confirm API returns only correctly matching records, count check.
 * 5. Test sorting by name and sort_order—validate ascending order strictness.
 * 6. Paginate (limit=2): Confirm each page fetches correct slice, page counts match ceil logic, all rows match by id.
 * 7. Negative filter: use unknown code, expect empty result. Malformed query (e.g., limit=-1): assert clear error thrown.
 * 8. Permission/authorization: simulate missing or invalid admin permission (document as comment if not possible).
 */
export async function test_api_aiShop_test_list_channels_with_various_filters_and_pagination_as_admin(
  connection: api.IConnection,
) {
  // 1. Create diverse aiShopChannels for meaningful test conditions:
  const channelPayloads: aiShopChannel.ICreate[] = [
    { code: "main2025", name: "메인 채널", enabled: true, sort_order: 1 },
    { code: "eventA", name: "이벤트 채널 A", enabled: false, sort_order: 4 },
    { code: "eventB", name: "이벤트 채널 B", enabled: true, sort_order: 2 },
    { code: "beta", name: "베타 채널", enabled: false, sort_order: 3 },
  ];
  const createdChannels: aiShopChannel[] = [];
  for (const payload of channelPayloads) {
    const ch = await api.functional.aiShop.channels.post(connection, { body: payload });
    typia.assert(ch);
    createdChannels.push(ch);
  }
  // Helper to fetch channels with flexible params
  async function fetchChannels(params: Partial<aiShopChannel.IRequest> = {}) {
    const page = await api.functional.aiShop.channels.patch(connection, {
      body: { ...params },
    });
    typia.assert(page);
    for (const row of page.data) typia.assert(row);
    return page;
  }

  // 2. List all channels without filter (should list all created):
  const allPage = await fetchChannels();
  TestValidator.equals("total record count matches")(allPage.pagination.records)(createdChannels.length);
  TestValidator.equals("page count math")
    (allPage.pagination.pages)(Math.ceil((allPage.pagination.records) / allPage.pagination.limit));
  const allCodes = allPage.data.map((ch) => ch.code);
  for (const { code } of channelPayloads) {
    TestValidator.predicate(`channel: ${code} listed`)(allCodes.includes(code));
  }

  // 3. Partial code search:
  const partSearch = await fetchChannels({ searchText: "event" });
  TestValidator.predicate("searchText event should match 2 channels")(partSearch.data.length === 2);
  for (const ch of partSearch.data) {
    typia.assert(ch);
    TestValidator.predicate("matched code includes event")(ch.code.includes("event"));
  }

  // 4. Filter enabled/disabled
  for (const enabled of [true, false]) {
    const page = await fetchChannels({ enabled });
    for (const ch of page.data) {
      typia.assert(ch);
      TestValidator.equals("enabled filter works")(ch.enabled)(enabled);
    }
    const expectCount = channelPayloads.filter((c) => c.enabled === enabled).length;
    TestValidator.equals(`enabled=${String(enabled)} count`)(page.pagination.records)(expectCount);
  }

  // 5. Sort checks: name, sort_order, composite sort
  const sortByName = await fetchChannels({ sort: ["name"] });
  const sortedNames = [...sortByName.data.map((d) => d.name)].sort();
  TestValidator.equals("sorted by name ASC")(sortByName.data.map((d) => d.name))(sortedNames);
  const sortByOrder = await fetchChannels({ sort: ["sort_order"] });
  const sortedOrders = [...sortByOrder.data.map((d) => d.sort_order)].sort((a, b) => a - b);
  TestValidator.equals("sorted by sort_order ASC")(sortByOrder.data.map((d) => d.sort_order))(sortedOrders);
  // Composite sort [enabled,sort_order]
  const sortByEnabledAndOrder = await fetchChannels({ sort: ["enabled", "sort_order"] });
  const compositeSort = (d: typeof sortByEnabledAndOrder.data[0]) => (d.enabled ? 0 : 1) * 1000 + d.sort_order;
  const expectedSorted = [...sortByEnabledAndOrder.data].sort((a, b) => compositeSort(a) - compositeSort(b));
  TestValidator.equals("composite sort works")(
    sortByEnabledAndOrder.data.map(compositeSort)
  )(expectedSorted.map(compositeSort));

  // 6. Pagination: pageSize = 2
  const pagedPage1 = await fetchChannels({ page: 1, limit: 2 });
  TestValidator.equals("paged limit")(pagedPage1.data.length)(2);
  TestValidator.equals("page index")(pagedPage1.pagination.current)(1);
  const pagedPage2 = await fetchChannels({ page: 2, limit: 2 });
  TestValidator.equals("paging next page")(pagedPage2.pagination.current)(2);
  const page1Ids = pagedPage1.data.map((d) => d.id);
  const page2Ids = pagedPage2.data.map((d) => d.id);
  TestValidator.predicate("page items unique")(page1Ids.every((id) => !page2Ids.includes(id)));
  const pagedAll = [...pagedPage1.data, ...pagedPage2.data];
  const pagedAllSorted = pagedAll.map((d) => d.id).sort();
  const allIdsSorted = allPage.data.map((d) => d.id).sort();
  TestValidator.equals("paged all IDs match full")(pagedAllSorted)(allIdsSorted);
  TestValidator.equals("paged total math")
    (pagedPage1.pagination.pages)(Math.ceil((allPage.pagination.records) / pagedPage1.pagination.limit));

  // 7. Invalid filter (unknown code):
  const badCodePage = await fetchChannels({ code: "nonexistent" });
  TestValidator.equals("bad code yields 0 result")(badCodePage.data.length)(0);
  // Invalid/malformed query (e.g., limit = -1)
  await TestValidator.error("invalid limit error")(async () => {
    await fetchChannels({ limit: -1 as any });
  });

  // 8. Permission check: simulate no/invalid auth (not implemented in this test; see doc)
  //   If feasible, forcibly remove or invalidate token and confirm patch call is rejected.
}

