 * This test verifies:
 * 1. Successful creation of a new channel with unique code, valid name, enabled boolean, and correct sort_order.
 * 2. Attempting to create another channel with the same code triggers a uniqueness error.
 * 3. Creation fails if required fields (name) are null or missing.
 * 4. Creation fails when a non-boolean value is used for enabled (input validation).
 * 5. Assumes operation is performed with admin-authenticated connection.
 *
 * Step-by-step process:
 * 1. Create a valid aiShopChannel using a unique code, valid name, enabled=true, and sort_order; assert values match response.
 * 2. Attempt to create another channel with the same code → expect error.
 * 3. Attempt channel creation with name set to null → expect error.
 * 4. Attempt channel creation with enabled set to a non-boolean (string) value → expect error.
 */
export async function test_api_aiShop_test_create_channel_with_unique_and_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Create a valid aiShopChannel with all required fields.
  const channelInput = {
    code: `code_${typia.random<string>().slice(0, 8)}`,
    name: `Test Channel ${RandomGenerator.alphabets(4)}`,
    enabled: true,
    sort_order: typia.random<number & tags.Type<"int32">>(),
  } satisfies aiShopChannel.ICreate;
  const created = await api.functional.aiShop.channels.post(connection, { body: channelInput });
