  TestValidator.equals("created code matches")(created.code)(channelInput.code);
  TestValidator.equals("created name matches")(created.name)(channelInput.name);
  TestValidator.equals("created enabled matches")(created.enabled)(channelInput.enabled);
  TestValidator.equals("created sort_order matches")(created.sort_order)(channelInput.sort_order);

  // 2. Attempt duplicate creation with same code → should trigger uniqueness error.
  await TestValidator.error("duplicate code should trigger error")(async () => {
