import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopChannel";

/**
 * E2E test for fully updating an aiShopChannel entity via PUT endpoint.
 *
 * This test ensures:
 * 1. Two channels are created and used to validate updates, uniqueness constraint, and error handling.
 * 2. A successful update updates all attributes (code, name, enabled, sort_order) of one channel using unique, valid data—validated by checking the response matches the expected input.
 * 3. An update attempt that would violate the unique code constraint triggers an error.
 * 4. Attempts to update with invalid/malformed data or invalid UUID result in validation errors.
 * 5. Attempts to update with insufficient admin privileges cannot be automated due to lack of alternate auth context in this setup, and is documented as skipped.
 *
 * Each stage validates both the type and the business logic enforcement for the endpoint.
 */
export async function test_api_aiShop_channels_test_update_channel_with_valid_data_and_uniqueness_violation(
  connection: api.IConnection,
) {
  // 1. Fixture setup: create two channels for uniqueness and update tests
  const channelA = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: "main-" + RandomGenerator.alphaNumeric(8),
      name: "Main Channel",
      enabled: true,
      sort_order: 1,
    } satisfies aiShopChannel.ICreate,
  });
  typia.assert(channelA);

  const channelB = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: "event-" + RandomGenerator.alphaNumeric(8),
      name: "Event Channel",
      enabled: false,
      sort_order: 2,
    } satisfies aiShopChannel.ICreate,
  });
  typia.assert(channelB);

  // 2. Successful full update of channelA
  const updatedBody = {
    code: "updated-" + RandomGenerator.alphaNumeric(8),
    name: "Updated Name",
    enabled: false,
    sort_order: 123,
  } satisfies aiShopChannel.IUpdate;
  const updated = await api.functional.aiShop.channels.putById(connection, {
    id: channelA.id,
    body: updatedBody,
  });
  typia.assert(updated);
  TestValidator.equals("code updated")(updated.code)(updatedBody.code);
  TestValidator.equals("name updated")(updated.name)(updatedBody.name);
  TestValidator.equals("enabled updated")(updated.enabled)(updatedBody.enabled);
  TestValidator.equals("sort_order updated")(updated.sort_order)(updatedBody.sort_order);

  // 3. Uniqueness conflict: attempt updating to duplicate code used by channelB
  TestValidator.error("code uniqueness conflict")(() =>
    api.functional.aiShop.channels.putById(connection, {
      id: channelA.id,
      body: {
        ...updatedBody,
        code: channelB.code, // duplicate code
      }
    })
  );

  // 4. Invalid/malformed update: missing required field 'name'
  TestValidator.error("missing required field")(() =>
    api.functional.aiShop.channels.putById(connection, {
      id: channelA.id,
      // TypeScript prevents truly missing required fields, so we cast to any for error
      body: {
        code: "missingname-" + RandomGenerator.alphaNumeric(5),
        // name missing
        enabled: true,
        sort_order: 8,
      } as any,
    })
  );

  // Malformed type: sort_order as string instead of int
  TestValidator.error("invalid type for sort_order")(() =>
    api.functional.aiShop.channels.putById(connection, {
      id: channelA.id,
      // Intentionally breaking type
      body: {
        code: "maltype-" + RandomGenerator.alphaNumeric(5),
        name: "Malformed",
        enabled: true,
        sort_order: "notanumber" as any,
      } as any,
    })
  );

  // Invalid UUID format for id
  TestValidator.error("invalid UUID")(() =>
    api.functional.aiShop.channels.putById(connection, {
      id: "not-a-uuid" as any,
      body: updatedBody,
    })
  );

  // 5. Authorization/role error scenario—skipped: cannot automate without a non-admin connection or alternate token handling.
}

