import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopChannel";
import type { aiShopSection } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated, filtered, and sorted retrieval of aiShopSection list with
 * correct meta-data, using diverse seeded channels/sections.
 *
 * This test ensures the /aiShop/sections PATCH endpoint retrieves a filtered,
 * paginated, and sorted subset of sections based on multiple fields.
 * It covers the full admin search use-case:
 *
 * 1. Seed: Create at least 2 channels (A, B)
 * 2. Seed: For each channel, create a diverse set of sections with all permutations of:
 *   - name (e.g. "Banner", "Deals", "Hot", "Footer")
 *   - enabled (true, false)
 *   - sort_order (1, 2, 99, ...)
 * 3. Test: List sections for channel A, filter by name, enabled
 * 4. Test: Apply pagination (e.g. limit=2, page=1), and sort by sort_order ASC
 * 5. Assert: Returned data contains only matching sections
 * 6. Assert: Data sorted as requested (ascending sort_order)
 * 7. Assert: Pagination meta correct: current page, limit, record count, pages
 */
export async function test_api_aiShop_test_list_ai_shop_sections_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. Seed test channels
  const channelA = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: "mainA-" + RandomGenerator.alphaNumeric(6),
      name: "Main A",
      enabled: true,
      sort_order: 1,
    },
  });
  typia.assert(channelA);
  const channelB = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: "subB-" + RandomGenerator.alphaNumeric(6),
      name: "Sub B",
      enabled: false,
      sort_order: 2,
    },
  });
  typia.assert(channelB);

  // 2. Seed sections under both channels with diverse names/enabled/sort_order
  const seedSections: [string, string, boolean, number][] = [
    [channelA.id, "Banner", true, 5],
    [channelA.id, "Deals", true, 2],
    [channelA.id, "Banner", false, 3],
    [channelA.id, "Hot", true, 1],
    [channelA.id, "Banner", true, 4],
    [channelB.id, "Banner", true, 1],
    [channelB.id, "Footer", false, 2],
  ];

  const createdSections: aiShopSection[] = [];
  for (const [ai_shop_channel_id, name, enabled, sort_order] of seedSections) {
    const section = await api.functional.aiShop.sections.post(connection, {
      body: {
        ai_shop_channel_id,
        code: name.toLowerCase() + "-" + RandomGenerator.alphaNumeric(4),
        name,
        sort_order,
        enabled,
      },
    });
    typia.assert(section);
    createdSections.push(section);
  }

  // 3. Retrieve: filter for Channel A, name="Banner", enabled=true
  const filterBody = {
    ai_shop_channel_id: channelA.id,
    name: "Banner",
    enabled: true,
    limit: 2,
    page: 1,
    sort: ["sort_order"],
  } satisfies aiShopSection.IRequest;

  const page = await api.functional.aiShop.sections.patch(connection, {
    body: filterBody,
  });
  typia.assert(page);

  // 4. Assert: Only relevant data returned
  const expected = createdSections
    .filter(
      (s) =>
        s.ai_shop_channel_id === channelA.id &&
        s.name === "Banner" &&
        s.enabled === true,
    )
