 * 2. Create a section using the first channel.
 * 3. Update all fields of the created section (change code, name, enabled, channel, and sort_order).
 * 4. Validate that the update response contains the new data and that the section ID has not changed.
 * 5. Ensure data integrity (timestamps are updated, fields match expected values).
 */
export async function test_api_aiShop_test_update_ai_shop_section_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create initial channel
  const origChannel = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: `ch1-${RandomGenerator.alphaNumeric(8)}`,
      name: `Original Channel ${RandomGenerator.alphaNumeric(4)}`,
      enabled: true,
      sort_order: 1,
    },
  });
  typia.assert(origChannel);

  // 2. Create another channel for update target
  const newChannel = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: `ch2-${RandomGenerator.alphaNumeric(8)}`,
      name: `Updated Channel ${RandomGenerator.alphaNumeric(4)}`,
