/**
 * 플랫폼 설정 리스트의 검색/필터/페이징/정렬 동작 및 오류처리를 검증하는 테스트
 *
 * - 플랫폼 관리자(authorization context implicit)로 환경설정 목록 조회 API의
 *   다양한 필터(pagination, search, sort, order) 파라미터 조합과 그 결과, 에러처리까지 검증한다.
 * - 적어도 1개의 테스트용 설정 레코드가 리스트에 보이도록 사전 등록.
 * - 페이징, 정렬, 필터 조합에 따라 정확히 동작하는지, 구문 오류/비정상 파라미터에 오류가 반환되는지 확인.
 *
 * [테스트 절차]
 * 1. 테스트용 환경설정 레코드 등록 (이후 검색/필터 대상으로 활용)
 * 2. 전체 리스트 조회(파라미터 없음)시 해당 레코드 포함 여부 확인
 * 3. 검색어 필터(search)로 조회시 정확 검색 결과 확인
 * 4. 페이징·정렬 조합(limit, sort, order)별 조회 및 결과/순서확인
 * 5. 비정상 파라미터(page 음수/limit=0 등) 에러 반환 확인
 */
export async function test_api_aiShop_configurations_test_list_configurations_with_search_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. 테스트 환경설정 레코드 생성 (유니크 데이터)
  const TEST_PARAM_NAME = `test_param_${RandomGenerator.alphaNumeric(8)}`;
  const TEST_PARAM_VALUE = RandomGenerator.alphaNumeric(12);
  const TEST_DESC = RandomGenerator.content()(1)();
  const created = await api.functional.aiShop.configurations.post(connection, {
    body: {
      param_name: TEST_PARAM_NAME,
      param_value: TEST_PARAM_VALUE,
      description: TEST_DESC,
    } satisfies aiShopConfigurations.ICreate,
  });
  typia.assert(created);

  // 2. 전체 리스트(파라미터 없음) — 방금 생성된 항목이 포함되어야 함
  const pageAll = await api.functional.aiShop.configurations.patch(connection, {
    body: {},
  });
  typia.assert(pageAll);
  const foundAll = pageAll.data.find(row => row.param_name === TEST_PARAM_NAME);
  TestValidator.predicate("새 레코드 전체조회 포함됨")(!!foundAll);

  // 3. 검색어(search) 파라미터 — 정확 필터 동작 확인
  const pageSearch = await api.functional.aiShop.configurations.patch(connection, {
    body: {
      search: TEST_PARAM_NAME,
    },
  });
  typia.assert(pageSearch);
  TestValidator.predicate("검색어 필터 동작")(!!pageSearch.data.find(row => row.param_name === TEST_PARAM_NAME));

  // 4. limit/paging/sort 조합 ASC
  const pageAsc = await api.functional.aiShop.configurations.patch(connection, {
    body: {
      page: 1,
      limit: 1,
      sort: "param_name",
      order: "asc",
    },
  });
  typia.assert(pageAsc);
  TestValidator.equals("limit=1 동작")(pageAsc.pagination.limit)(1);
  TestValidator.equals("page=1 동작")(pageAsc.pagination.current)(1);

  // 5. DESC 정렬 동작 검증
  const pageDesc = await api.functional.aiShop.configurations.patch(connection, {
    body: {
      page: 1,
      limit: 1,
      sort: "param_name",
      order: "desc",
    },
  });
  typia.assert(pageDesc);
  TestValidator.equals("limit=1 DESC")(pageDesc.pagination.limit)(1);
  TestValidator.equals("page=1 DESC")(pageDesc.pagination.current)(1);
  if (pageAsc.data.length && pageDesc.data.length && pageAsc.data[0].id !== pageDesc.data[0].id) {
    TestValidator.notEquals("ASC/DESC 순서불일치")(pageAsc.data[0].id)(pageDesc.data[0].id);
  }

  // 6. 잘못된 page/limit 파라미터로 에러 발생 확인
  await TestValidator.error("음수 page 오류")(
    async () => {
      await api.functional.aiShop.configurations.patch(connection, {
        body: {
          page: -1,
        },
      });
    },
  );
  await TestValidator.error("limit=0 오류")(
    async () => {
      await api.functional.aiShop.configurations.patch(connection, {
        body: {
          limit: 0,
        },
      });
    },
  );
}

