  typia.assert(result2);
  TestValidator.equals("should not allow repeated delete of non-existent record")(result2.ok)(false);
  TestValidator.predicate("should include a descriptive error message on repeated attempt")(typeof result2.message === "string" && result2.message.length > 0);
}

