 * 1. Create a new configuration as admin (using POST /aiShop/configurations).
 * 2. Delete the created configuration by its UUID (DELETE /aiShop/configurations/{id}).
 * 3. Re-attempt to delete the same configuration UUID again (DELETE /aiShop/configurations/{id}).
 * 4. Assert: The first delete result is ok==true, the second is ok==false (idempotency contract), with all responses type-checked and no lingering side effects.
 */
export async function test_api_aiShop_configurations_test_delete_duplicate_invocation_idempotence(
  connection: api.IConnection,
) {
