import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopChannel";
import type { aiShopCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopCategories";
import type { IPageAiShopCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageAiShopCategories";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for paginated and filtered aiShop category listing.
 *
 * This test validates retrieving paginated, filtered, and searchable lists of aiShop categories
 * with channelId, enabled status, search term, and pagination parameters. It covers data setup, filter/search validation, and error handling.
 *
 * Workflow:
 * 1. Create two aiShopChannels (A and B) with distinct codes and names
 * 2. For channelA, create 4 categories (different enabled, name, code)
 *    - 2 enabled, 2 disabled, name/code includes 'Q' for search
 * 3. For channelB, create 2 categories
 * 4. List categories for channelA, enabled=true (expect only those)
 * 5. List categories with search='Q' (case-insensitive, expect only those with Q)
 * 6. List paginated (page=1, limit=2), expect proper count/meta
 * 7. Negative: send invalid limit (e.g. -1), expect error
 */
export async function test_api_aiShop_test_list_categories_with_pagination_and_filtering(connection: api.IConnection) {
  // 1. Create two channels with unique codes
  const channelA = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: 'Channel A',
      enabled: true,
      sort_order: 1,
    },
  });
  typia.assert(channelA);
  const channelB = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: 'Channel B',
      enabled: true,
      sort_order: 2,
    },
  });
  typia.assert(channelB);

  // 2. Create categories for channels
  const cat_defs = [
    // Channel A
    {
      ai_shop_channel_id: channelA.id,
      code: 'light',
      name: 'AlphaQ',
      enabled: true,
      sort_order: 1,
    },
    {
      ai_shop_channel_id: channelA.id,
      code: 'dark',
      name: 'BetaX',
      enabled: false,
      sort_order: 2,
    },
    {
      ai_shop_channel_id: channelA.id,
      code: 'heavy',
      name: 'GammaY',
      enabled: true,
      sort_order: 3,
    },
    {
      ai_shop_channel_id: channelA.id,
      code: 'mid',
      name: 'OmegaQ',
      enabled: false,
      sort_order: 4,
    },
    // Channel B
    {
      ai_shop_channel_id: channelB.id,
      code: 'misc',
      name: 'DeltaP',
      enabled: true,
      sort_order: 1,
    },
    {
      ai_shop_channel_id: channelB.id,
      code: 'side',
      name: 'SigmaL',
      enabled: false,
      sort_order: 2,
    },
  ];
  const categories = [];
  for (const def of cat_defs) {
    const created = await api.functional.aiShop.categories.post(connection, {
      body: def,
    });
    typia.assert(created);
    categories.push(created);
  }

  // 4. List categories for channelA, enabled=true
  const filterA_enabled = await api.functional.aiShop.categories.patch(connection, {
    body: {
      channelId: channelA.id,
      enabled: true,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(filterA_enabled);
  const expectedA_enabled = categories.filter(c => c.ai_shop_channel_id === channelA.id && c.enabled);
  TestValidator.equals('filter by channel & enabled')(filterA_enabled.data.map(d => d.id).sort())(expectedA_enabled.map(d => d.id).sort());
  TestValidator.equals('pagination meta for filterA_enabled')(filterA_enabled.pagination.records)(expectedA_enabled.length);

  // 5. List categories with search 'Q'
  const searchQ = await api.functional.aiShop.categories.patch(connection, {
    body: {
      search: 'Q',
      page: 1,
      limit: 10,
    },
  });
  typia.assert(searchQ);
  const expectQ = categories.filter(c => /Q/i.test(c.name) || /Q/i.test(c.code));
  TestValidator.equals('search Q')(searchQ.data.map(d => d.id).sort())(expectQ.map(d => d.id).sort());

  // 6. List paginated (page=1, limit=2)
  const page1 = await api.functional.aiShop.categories.patch(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(page1);
  TestValidator.equals('page1 count')(page1.data.length)(2);
  TestValidator.equals('pagination meta')(page1.pagination.current)(1);
  TestValidator.equals('pagination limit')(page1.pagination.limit)(2);

  // 7. Negative: invalid limit
  await TestValidator.error('invalid limit throws')(
    async () => {
      await api.functional.aiShop.categories.patch(connection, {
        body: {
          page: 1,
          limit: -1,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
