 * This test ensures that when provided with the ID of an existing (recently created) AI Shop category, the details endpoint returns all required fields correctly and the data is consistent with the record at creation time.
 *
 * Steps:
 * 1. Create a new category with randomized but valid input data (covering all required fields including channel ID, code, name, sort order, enabled flag, etc.)
 * 2. Immediately retrieve the category details using its returned ID via the GET /aiShop/categories/{id} endpoint.
 * 3. Assert that all required fields are present in the response and that their values match those from the creation response (except for server-managed fields like timestamps and IDs, which need type/format validation).
 * 4. Confirm additionally that ID, ai_shop_channel_id, code, and name are exactly as given at creation.
 */
export async function test_api_aiShop_test_get_category_details_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new category
  const createInput: aiShopCategories.ICreate = {
    ai_shop_channel_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(1),
    sort_order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
    parent_id: null,
  };

  const created: aiShopCategories = await api.functional.aiShop.categories.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Retrieve the category details by its ID
