  TestValidator.equals("Name matches")(fetched.name)(created.name);
  TestValidator.equals("Sort order matches")(fetched.sort_order)(created.sort_order);
  TestValidator.equals("Enabled matches")(fetched.enabled)(created.enabled);

  // 4. Type/format checks for timestamps (not strict value match; should be valid ISO strings)
