 *
 * 1. Create a new category (using the POST /aiShop/categories API)
 * 2. Update all updatable (mutable) fields: code, name, parent_id, sort_order, enabled, ai_shop_channel_id
 * 3. Assert that:
 *    - The API returns the updated record
 *    - All mutable fields are changed to their updated values
 *    - Immutable fields (id, created_at) are not changed
 *    - Non-updated fields (e.g., id) remain as before
 */
export async function test_api_aiShop_categories_test_update_category_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create an initial category
  const createInput: aiShopCategories.ICreate = {
    ai_shop_channel_id: typia.random<string & tags.Format<"uuid">>(),
    parent_id: null,
    code: "CAT001",
    name: "Initial Category",
    sort_order: 1,
    enabled: true,
  };
  const original: aiShopCategories = await api.functional.aiShop.categories.post(connection, { body: createInput });
  typia.assert(original);

  // 2. Prepare update values (change code, name, parent_id, sort_order, enabled, ai_shop_channel_id)
  const updateInput: aiShopCategories.IUpdate = {
    ai_shop_channel_id: typia.random<string & tags.Format<"uuid">>(),
    parent_id: typia.random<string & tags.Format<"uuid">>(),
    code: "CAT002",
    name: "Updated Category",
    sort_order: 99,
    enabled: false,
  };

  // 3. Call the update endpoint
  const updated: aiShopCategories = await api.functional.aiShop.categories.putById(connection, { id: original.id, body: updateInput });
