  TestValidator.equals("id remains unchanged")(updated.id)(original.id);
  TestValidator.equals("channel updated")(updated.ai_shop_channel_id)(updateInput.ai_shop_channel_id);
  TestValidator.equals("parent updated")(updated.parent_id)(updateInput.parent_id);
