 * This test validates that updating an aiShopCategories record so that its `code` collides with another category's code (within the same parent and channel) will result in an error, confirming code uniqueness is enforced by the API. The scenario is as follows:
 *
 * 1. Create an aiShopChannel for scope (since channel is required for every category).
 * 2. Create a single parent/root category for use as common parent (nullable parent_id for ICreate).
 * 3. Create CategoryA and CategoryB as children under the same parent & channel, with different random `code` values.
 * 4. Attempt to update CategoryA, changing only its `code` to that of CategoryB (all other props remain as originally set for A). The `ai_shop_channel_id` and `parent_id` are not changed.
 * 5. The update request should result in an error (uniqueness constraint violation). The test asserts that an error is thrown, meaning category `code` uniqueness under same parent and channel is enforced.
 *
 * Steps:
 * 1. Create aiShopChannel (POST /aiShop/channels)
 * 2. Create parent/root category (POST /aiShop/categories)
 * 3. Create CategoryA (POST /aiShop/categories)
 * 4. Create CategoryB (POST /aiShop/categories)
 * 5. Update CategoryA to have CategoryB's code (PUT /aiShop/categories/:id) - expect API error
 */
export async function test_api_aiShop_test_update_category_with_duplicate_code_in_same_parent_channel(
  connection: api.IConnection,
) {
  // 1. Create aiShopChannel
  const channel = await api.functional.aiShop.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      enabled: true,
      sort_order: 1,
    },
  });
  typia.assert(channel);

  // 2. Create parent/root category
  const parent = await api.functional.aiShop.categories.post(connection, {
    body: {
      ai_shop_channel_id: channel.id,
      parent_id: null, // root level
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      sort_order: 1,
      enabled: true,
    },
  });
  typia.assert(parent);

  // 3. Create CategoryA
  const categoryA = await api.functional.aiShop.categories.post(connection, {
    body: {
      ai_shop_channel_id: channel.id,
      parent_id: parent.id,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      sort_order: 11,
      enabled: true,
    },
  });
  typia.assert(categoryA);

  // 4. Create CategoryB
  const categoryB = await api.functional.aiShop.categories.post(connection, {
    body: {
      ai_shop_channel_id: channel.id,
      parent_id: parent.id,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      sort_order: 22,
      enabled: true,
    },
  });
  typia.assert(categoryB);

  // 5. Attempt to update CategoryA's code to B's code (should fail)
  await TestValidator.error("Category update with duplicate code under same parent/channel should fail")(
    async () => {
      await api.functional.aiShop.categories.putById(connection, {
        id: categoryA.id,
        body: {
          ai_shop_channel_id: channel.id,
          parent_id: parent.id,
          code: categoryB.code, // duplicate
          name: categoryA.name,
          sort_order: categoryA.sort_order,
          enabled: categoryA.enabled,
        },
      });
    },
  );
}

