import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopCategories";
import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * 카테고리 삭제 실패: 자식 카테고리(또는 상품 참조)가 있을 때 삭제 불가
 *
 * 이 테스트는 트리 구조의 카테고리에서 자료 무결성이 지켜지는지 검증한다.
 *
 * 시나리오:
 * 1. 테스트용 채널 UUID를 준비한다.
 * 2. 해당 채널에 최상위(parent_id=null) 부모 카테고리를 생성한다.
 * 3. 부모 카테고리의 하위에 자식 카테고리를 parent_id로 연결하여 생성한다.
 * 4. 부모 카테고리 id로 삭제 시도를 한다.
 * 5. 서버가 자식(혹은 상품/타 엔티티 참조 시) 존재로 인해 삭제에 실패했음을 반환해야 한다.
 *   - 삭제 결과(ok)가 false여야 하며, message에도 실패 사유가 기재되어야 한다.
 *   - 성공적으로 삭제될 경우(삭제방지 실패)는 에러.
 * 6. 이후 cleanup(별도 없음, cascade 제거 API 없는 가정) 불필요.
 */
export async function test_api_aiShop_categories_test_delete_category_with_child_categories_or_products(
  connection: api.IConnection,
) {
  // 1. 테스트용 채널 UUID 준비
  const channelId = typia.random<string & tags.Format<"uuid">>();

  // 2. 부모 카테고리 생성
  const parentCategory = await api.functional.aiShop.categories.post(
    connection,
    {
      body: {
        ai_shop_channel_id: channelId,
        parent_id: null,
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.name(),
        sort_order: 1,
        enabled: true,
      } satisfies aiShopCategories.ICreate,
    },
  );
  typia.assert(parentCategory);

  // 3. 자식 카테고리 생성 (부모의 id를 parent_id로)
  const childCategory = await api.functional.aiShop.categories.post(
    connection,
    {
      body: {
        ai_shop_channel_id: channelId,
        parent_id: parentCategory.id,
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.name(),
        sort_order: 2,
        enabled: true,
      } satisfies aiShopCategories.ICreate,
    },
  );
  typia.assert(childCategory);

  // 4~5. 부모 카테고리 삭제 시도 → 자식 존재로 인해 삭제 실패가 나야 함
  const deleteResult = await api.functional.aiShop.categories.eraseById(
    connection,
    {
      id: parentCategory.id,
    },
  );
  typia.assert(deleteResult);
  // 5.1. 삭제 ok가 false여야 하고, message에 사유가 꼭 있어야 함
  TestValidator.equals("category delete blocked due to child existence")(deleteResult.ok)(false);
  TestValidator.predicate("delete failure message present")(!!deleteResult.message && typeof deleteResult.message === "string" && deleteResult.message.length > 0);
}

