 * - 여러 유형의 audit log를 등록 후, 복합적인 필터 조건, 페이지네이션과 정렬 옵션을 랜덤/조합하여 조회 시도
 * - 각 단계별로 필터링, 페이징, 정렬, 메타데이터(pagination) 및 데이터 유효성 assert
 * - 이 테스트는 어드민 권한 전제 하이며, 인증 API가 별도로 제공되지 않는 환경에서는 생략 가능
 *
 * 테스트 단계:
 * 1. 충분한 수(15~20개)의 다양한 event_type, actor_role, target_table, created_at 값을 가진 audit log를 사전 등록한다
 * 2. 단일 event_type 필터로 로그 검색 및 결과 assert
 * 3. 복수 event_type & actor_role 필터 조합으로 검색 및 결과 assert
 * 4. target_table+created_at 범위 필터 테스트 및 결과 assert
 * 5. 페이지네이션(meta 정보 및 데이터 slicing) 검증
 * 6. 최신순 정렬(sort=-created_at) 결과 정상 여부 검증
 */
export async function test_api_aiShop_test_list_audit_logs_with_filters_and_pagination_success_admin(
  connection: api.IConnection,
) {
  // 1. 다양한 조합의 감사 로그 15~20개 사전 생성 (필터/페이징/정렬 검증용)
  const baseTime = new Date();
  const logInputs: IAiShopAuditLog.ICreate[] = [
    {
      event_id: `LOGIN-AD-1`,
      event_type: 'USER_LOGIN',
      actor_id: typia.random<string & tags.Format<'uuid'>>(),
      actor_role: 'admin',
      target_table: 'ai_shop_users',
      target_id: typia.random<string & tags.Format<'uuid'>>(),
      details: '{"ip": "127.0.0.1"}',
    },
    {
      event_id: `ORDER-CANCEL-1`,
      event_type: 'ORDER_CANCELED',
      actor_id: typia.random<string & tags.Format<'uuid'>>(),
      actor_role: 'admin',
      target_table: 'ai_shop_orders',
      target_id: typia.random<string & tags.Format<'uuid'>>(),
      details: '{"reason": "customer requested"}',
    },
    {
      event_id: `ORDER-NEW-1`,
      event_type: 'ORDER_CREATED',
      actor_id: typia.random<string & tags.Format<'uuid'>>(),
      actor_role: 'customer',
      target_table: 'ai_shop_orders',
      target_id: typia.random<string & tags.Format<'uuid'>>(),
      details: '{"order_value": 15000}',
    },
    {
      event_id: `SYS-EVENT-1`,
      event_type: 'SYSTEM_MAINTENANCE',
      actor_id: null,
      actor_role: null,
      target_table: null,
      target_id: null,
      details: null,
    },
  ];
  // 나머지(사이즈 맞추기용) 랜덤 데이터 추가
  while (logInputs.length < 17) {
    logInputs.push({
      event_id: `RANDOM-${logInputs.length + 1}-${typia.random<number & tags.Type<'int32'>>()}`,
      event_type: RandomGenerator.pick(['USER_LOGIN', 'ORDER_CANCELED', 'ORDER_CREATED', 'SYSTEM_MAINTENANCE', 'DATA_EXPORT']),
      actor_id: Math.random() < 0.8 ? typia.random<string & tags.Format<'uuid'>>() : null,
      actor_role: RandomGenerator.pick(['admin', 'customer', 'seller', null]),
      target_table: RandomGenerator.pick(['ai_shop_orders', 'ai_shop_users', null]),
      target_id: Math.random() < 0.8 ? typia.random<string & tags.Format<'uuid'>>() : null,
      details: Math.random() < 0.7 ? JSON.stringify({ rand: Math.random() }) : null,
    });
  }

  const createdIds: string[] = [];
  for (let idx = 0; idx < logInputs.length; ++idx) {
    const output = await api.functional.aiShop.auditLogs.post(connection, { body: logInputs[idx] });
    typia.assert(output);
    createdIds.push(output.id);
  }

  // 2. event_type='USER_LOGIN'로만 단건 필터
  let response = await api.functional.aiShop.auditLogs.patch(connection, {
    body: {
      page: 1,
      limit: 10,
      filter: { event_type: 'USER_LOGIN' },
    } satisfies IAiShopAuditLog.IRequest,
  });
  typia.assert(response);
  TestValidator.predicate('USER_LOGIN만 조회됨')(response.data.every(x => x.event_type === 'USER_LOGIN'));

  // 3. event_type+actor_role 복수조건 필터
  response = await api.functional.aiShop.auditLogs.patch(connection, {
    body: {
      page: 1,
      limit: 10,
      filter: {
        event_type: ['ORDER_CANCELED', 'ORDER_CREATED'],
        actor_role: ['admin', 'customer'],
      },
    } satisfies IAiShopAuditLog.IRequest,
  });
  typia.assert(response);
  TestValidator.predicate('주문 관련+role')(response.data.every(x => ['ORDER_CANCELED','ORDER_CREATED'].includes(x.event_type)));

  // 4. target_table+created_at 날짜필터
  const yesterday = new Date(baseTime.getTime() - 24*3600*1000);
  response = await api.functional.aiShop.auditLogs.patch(connection, {
    body: {
      page: 1,
      limit: 10,
      filter: {
        target_table: 'ai_shop_orders',
        created_at: {
          gte: yesterday.toISOString(),
          lte: baseTime.toISOString(),
        },
      },
    } satisfies IAiShopAuditLog.IRequest,
  });
  typia.assert(response);
  TestValidator.predicate('ai_shop_orders+날짜')(response.data.every(x => x.target_table === 'ai_shop_orders' && new Date(x.created_at) >= yesterday && new Date(x.created_at) <= baseTime));

  // 5. 페이지네이션 및 메타 검증
  response = await api.functional.aiShop.auditLogs.patch(connection, {
    body: {
      page: 1,
      limit: 2,
      filter: null,
    } satisfies IAiShopAuditLog.IRequest,
  });
  typia.assert(response);
  TestValidator.equals('limit=2 사이즈')(response.pagination.limit)(2);
  TestValidator.predicate('2개 반환')(response.data.length === 2);

  // 6. sort=-created_at(최신순) 검증
  response = await api.functional.aiShop.auditLogs.patch(connection, {
    body: {
      page: 1,
      limit: 5,
      sort: '-created_at',
    } satisfies IAiShopAuditLog.IRequest,
  });
  typia.assert(response);
  for (let i = 1; i < response.data.length; ++i) {
    TestValidator.predicate(`desc 정렬 ${i}`)(new Date(response.data[i-1].created_at) >= new Date(response.data[i].created_at));
  }
}

