 * 3. Validate that the retrieved record matches exactly what was inserted for business fields (event_id, event_type, actor_id, actor_role, target_table, target_id, details), except for id and created_at which are system-generated and format-verified only.
 * 4. Use type and field assertions to guarantee proper data contract, field integrity, and correct business logic.
 */
export async function test_api_aiShop_test_get_audit_log_detail_success_admin(
  connection: api.IConnection,
) {
