import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopAuditLog";

/**
 * 테스트: 필수 메타데이터 누락/부적합 시 감사 로그 생성 실패
 *
 * 해당 테스트는 감사 로그(Audit Log) API에서 필수 메타데이터가 누락되거나 잘못된 값이 입력될 때
 * 422 오류를 반환하는지 검증한다.
 *
 * 비즈니스 규칙 및 OpenAPI 스키마 기준으로 TypeScript 타입으로 표현 가능한 범위 내 사례만 검증한다.
 * 즉, event_type의 빈 문자열 등 런타임 유효성 검사만 테스트한다.
 * (TypeScript 필수값 누락, 존재하지 않는 필드는 테스트 제외)
 *
 * 1. event_type에 빈 문자열 전달 → 422 오류 기대
 * 2. event_id에 빈 문자열 전달 → 422 오류 기대
 * 3. actor_id는 옵션(선택) 값이므로 null, undefined로 제공 가능함을 확인
 * 4. 모든 필수 필드 유효값으로 정상 생성 → 성공 확인
 */
export async function test_api_aiShop_test_create_audit_log_missing_required_metadata(
  connection: api.IConnection,
) {
  // 1. event_type에 빈 문자열 전달 → 422 오류 기대
  await TestValidator.error("event_type을 빈 문자열로 전달하면 422 오류")(async () => {
    await api.functional.aiShop.auditLogs.post(connection, {
      body: {
        event_id: "EVT-20250722-001",
        event_type: "",
      },
    });
  });

  // 2. event_id에 빈 문자열 전달 → 422 오류 기대
  await TestValidator.error("event_id를 빈 문자열로 전달하면 422 오류")(async () => {
    await api.functional.aiShop.auditLogs.post(connection, {
      body: {
        event_id: "",
        event_type: "USER_LOGIN",
      },
    });
  });

  // 3. actor_id: undefined/생략 허용 여부 확인 (정상 동작)
  const result1 = await api.functional.aiShop.auditLogs.post(connection, {
    body: {
      event_id: "EVT-20250722-002",
      event_type: "USER_LOGIN",
      // actor_id 생략
    },
  });
  typia.assert(result1);

  // 4. actor_id: null 값 제공 허용 여부 확인 (정상 동작)
  const result2 = await api.functional.aiShop.auditLogs.post(connection, {
    body: {
      event_id: "EVT-20250722-003",
      event_type: "ORDER_CREATED",
      actor_id: null,
    },
  });
