/**
 * 유일성 규칙에 따른 event_id 중복 불가 테스트.
 *
 * 1. 특정 event_id로 감사 로그를 정상적으로 생성한다.
 * 2. 같은 event_id로 다시 로그 생성을 시도하면 중복 검증 에러(혹은 409/422 validation error)가 발생해야 한다.
 *   - 이때, 실제로 중복 event_id 정책이 DB 레벨 및 API 유효성에서 강제되는지 확인한다.
 *
 * 시나리오 설명:
 *  - 감사 로그는 event_id의 전역 유일성이 DB와 API에서 보장되어야 하며,
 *    중복 입력 시 실패하는 것이 비즈니스 및 컴플라이언스 정책상 중요하다.
 *
 * 검증 포인트:
 *  - 첫 번째 생성은 반드시 성공해야 한다 (event_id 인입 성공).
 *  - 두 번째 중복 event_id 생성 시 반드시 런타임 에러(409/422)가 발생해야 한다.
 *
 * 테스트 단계:
 *   1. auditLogData(동일 event_id) 준비
 *   2. auditLogs.post로 정상 생성
 *   3. auditLogs.post 동일 event_id로 재시도 → 에러 발생 확인
 */
export async function test_api_aiShop_test_create_audit_log_duplicate_event_id_error(connection: api.IConnection) {
  // 1. 감사 로그 생성 입력값 준비 (event_id 고정)
  const eventId = `DUP-EVENT-${typia.random<number & tags.Type<"uint32">>()}`;
  const auditLogInput: IAiShopAuditLog.ICreate = {
    event_id: eventId,
    event_type: "ORDER_CANCELED",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_role: "customer",
    target_table: "ai_shop_orders",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    details: JSON.stringify({ reason: "for duplicate event_id test" }),
  };

  // 2. 최초 감사 로그 정상 생성
  const log1 = await api.functional.aiShop.auditLogs.post(connection, {
    body: auditLogInput,
  });
  typia.assert(log1);
  TestValidator.equals("event_id 최초 생성 성공")(log1.event_id)(eventId);

  // 3. 중복 event_id로 감사 로그 재생성 시도 → 반드시 에러 발생
  await TestValidator.error("event_id 중복에 따른 409/422 validation error")(
    async () => {
      await api.functional.aiShop.auditLogs.post(connection, {
        body: auditLogInput,
      });
    },
  );
}

