 *
 * [비즈니스 맥락]
 * ai_shop_files에 새로운 파일을 업로드하며(메타데이터 등록) 이때 원본 파일명, storage URI, mime type, 파일 크기, 업로더 이름, 업로드 일시 등 주요 메타데이터를 함께 등록합니다. 업로드 성공 시 전체 필드가 반환되어야 하며, 이후 파일 목록 조회 및 단건 조회에서 해당 파일이 존재함을 확인해야 합니다.
 *
 * [테스트 프로세스]
 * 1. 임의의 메타데이터로 파일 업로드 등록 요청(POST) 수행
 * 2. 파일 등록 결과의 모든 데이터가 제대로 반환되었는지 확인(typia.assert 및 필드 값 검증)
 * 3. 목록 조회 API 및 상세조회 API가 없는 상황이므로, 등록 결과의 반환값만 비즈니스적으로 검증
 *
 * [추가 검증]
 * - 반환된 객체의 모든 필드가 정상 값 및 입력값과 논리적으로 연관되어 있음(특히 original_name, uri, mime_type, size_bytes 등)
 * - 입력값 그대로 반환되는 항목은 동등성(assert), 자동 생성되는 항목(id, uploaded_at 등)은 포맷 검증
 *
 * [오류/엣지 케이스] (실장 불가 요소)
 * - 목록/상세 조회 API가 제공되지 않으므로, 업로드 직후 데이터의 목록/재확인 테스트는 불가
 * - 실제 파일 업로드 대신 메타데이터만 검증
 */
export async function test_api_aiShop_test_upload_file_with_valid_metadata(
  connection: api.IConnection,
) {
  // 1. 임의의 정합적 파일 메타데이터 생성
  const input = {
    original_name: "test-image.png",
    uri: `s3://ai-shop-uploads/${typia.random<string & tags.Format<"uuid">>()}.png`,
    mime_type: "image/png",
    size_bytes: 204800, // 200KB
    uploader_name: "테스트유저",
    uploaded_at: new Date().toISOString(),
  };

  // 2. 파일 업로드 메타데이터 등록 요청
  const output = await api.functional.aiShop.files.post(connection, {
    body: input,
  });
  typia.assert(output);

  // 3. 반환 값 필드 검증
  TestValidator.equals("original_name")(output.original_name)(input.original_name);
  TestValidator.equals("uri")(output.uri)(input.uri);
  TestValidator.equals("mime_type")(output.mime_type)(input.mime_type);
  TestValidator.equals("size_bytes")(output.size_bytes)(input.size_bytes);
  TestValidator.equals("uploader_name")(output.uploader_name)(input.uploader_name);

  // id(자동 생성), uploaded_at(ISO 포맷) 검증
  TestValidator.predicate("id is uuid")(
    typeof output.id === "string" &&
    /^[0-9a-fA-F-]{36}$/.test(output.id),
  );
  TestValidator.predicate("uploaded_at is ISO8601 date-time")(
    typeof output.uploaded_at === "string" &&
    !isNaN(new Date(output.uploaded_at).getTime()),
  );
}

