 *
 * This test verifies that the aiShop/files upload API enforces file URI integrity and validation rules.
 *
 * Business context: The system must prevent multiple file records having the same storage URI (for uniqueness/integrity)
 * and reject file uploads with invalid or ill-formatted URIs (as required for downstream processing and security).
 *
 * Steps:
 * 1. Upload a valid file with a unique URI.
 * 2. Attempt to upload another file with the same URI (should throw conflict/integrity error; no duplicate is allowed).
 * 3. Attempt to upload a file using an invalid/ill-formatted URI (should throw validation error; no file entry is created).
 */
export async function test_api_aiShop_test_upload_file_with_duplicate_uri_or_invalid_uri(
  connection: api.IConnection,
) {
