/**
 * 파일 메타데이터(original_name, mime_type, uploader_name) 수정 성공 (admin 또는 업로더)
 *
 * 이 테스트는 다음을 검증한다:
 * - 파일을 업로드(생성)한 뒤, original_name/mime_type/uploader_name 3개 메타데이터를 정상적으로 업데이트(수정)할 수 있음
 * - 수정이 허용되지 않는 필드(id/uri/size_bytes/uploaded_at)는 절대 변경되지 않고, editable 필드의 변경만 API 응답에 반영됨
 * - 기타 감사 로그(변경 이력 기록)는 이 테스트에서 직접 검증 대상이 아님 (API 스펙상 반환 값이 변경 반영 여부만 확인)
 *
 * [테스트 절차]
 * 1. 파일 업로드: 등록 가능한 메타데이터 값으로 파일을 신규 생성한다.
 * 2. 메타데이터 수정: original_name, mime_type, uploader_name 필드를 새로운 값으로 일괄 변경한다.
 * 3. 응답 검증: 반환된 수정 내용에서 변경(편집) 가능한 필드는 실제로 바뀌었는지, 변경 불가 필드는 그대로 유지되었는지 각각 검증한다.
 *   (id/uri/size_bytes/uploaded_at 불변, editable 항목은 input대로 적용 여부 비교)
 */
export async function test_api_aiShop_test_update_file_metadata_success_by_admin(
  connection: api.IConnection,
) {
  // 1. 파일 업로드 (등록용 메타데이터)
  const created: IAiShopFile = await api.functional.aiShop.files.post(
    connection,
    {
      body: {
        original_name: "init_example_원본.pdf",
        uri: `/files/${typia.random<string>()}-init`,
        mime_type: "application/pdf",
        size_bytes: 40960,
        uploader_name: "테스트업로더",
        uploaded_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(created);

  // 2. 메타데이터 업데이트 실행 (수정 가능한 필드만)
  const updateMeta: IAiShopFile.IUpdate = {
    original_name: "edit_수정됨.xlsx",
    mime_type: "application/vnd.ms-excel",
    uploader_name: "관리자수정자",
  };
  const updated: IAiShopFile = await api.functional.aiShop.files.putById(
    connection,
    {
      id: created.id,
      body: updateMeta,
    },
  );
  typia.assert(updated);

  // 3. 필드 유지/변경 검증: 수정불가 필드는 그대로, 수정 요청 값은 반영 확인
  TestValidator.equals("id 동일")(updated.id)(created.id);
  TestValidator.equals("uri 동일")(updated.uri)(created.uri);
  TestValidator.equals("size_bytes 동일")(updated.size_bytes)(created.size_bytes);
  TestValidator.equals("uploaded_at 동일")(updated.uploaded_at)(created.uploaded_at);

  TestValidator.notEquals("original_name 변경")(updated.original_name)(created.original_name);
  TestValidator.notEquals("mime_type 변경")(updated.mime_type)(created.mime_type);
  TestValidator.notEquals("uploader_name 변경")(updated.uploader_name)(created.uploader_name);
  TestValidator.equals("original_name 기대값")(updated.original_name)(updateMeta.original_name);
  TestValidator.equals("mime_type 기대값")(updated.mime_type)(updateMeta.mime_type);
  TestValidator.equals("uploader_name 기대값")(updated.uploader_name)(updateMeta.uploader_name);
}

