import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopFile";

/**
 * Test that deleting a file is forbidden for non-owner/non-admin users and the file remains.
 *
 * This test enforces the business rule that only the uploader (owner) or
 * an admin can delete files. The workflow is as follows:
 *
 * 1. Upload a file as another user (simulated User A) using one connection instance.
 * 2. Attempt to delete the uploaded file as a different user (simulated User B)
 *    by using a separate connection (with default/no upload privilege for the file).
 * 3. Confirm that the deletion attempt returns a 403 Forbidden error.
 * 4. Since only POST and DELETE endpoints are available, we cannot directly re-fetch
 *    the file to confirm existence. However, deletion failure by 403 implies persistence
 *    of the file as per business logic enforced by API contract.
 */
export async function test_api_aiShop_test_delete_file_forbidden_for_non_owner(connection: api.IConnection) {
  // 1. Upload a file as User A (simulated by a fresh connection instance)
  const connectionA = { ...connection };
  const file = await api.functional.aiShop.files.post(connectionA, {
    body: {
      original_name: "forbidden-test-file.dat",
      uri: `urn:uuid:${typia.random<string & tags.Format<"uuid">>()}`,
      mime_type: "application/octet-stream",
      size_bytes: 128,
      uploader_name: "UserA (not current)",
      uploaded_at: new Date().toISOString(),
    } satisfies IAiShopFile.ICreate,
  });
  typia.assert(file);

  // 2. Attempt to delete as another user (User B, using provided connection)
  //    (Assumes current connection does not match uploader or admin)
  await TestValidator.error("forbidden delete as non-owner/non-admin")(
    async () => {
      await api.functional.aiShop.files.eraseById(connection, {
        id: file.id,
      });
    },
  );
  // 3. Confirm: The file should still exist (cannot directly GET, but absence of
  //    success confirms persistence under contract).
}

